def func(self, value, unused=0, named=False):
    if unused < 0 or unused > 7:
        raise ASN1EncodeError('Unused bit count must be between 0 and 7')
    if isinstance(value, bytes):
        if unused:
            if not value:
                raise ASN1EncodeError("Can't have unused bits with empty value")
            elif value[-1] & (1 << unused) - 1:
                raise ASN1EncodeError('Unused bits in value should be zero')
    elif isinstance(value, str):
        if unused:
            raise ASN1EncodeError('Unused bit count should not be set when providing a string')
        used = len(value) % 8
        unused = 8 - used if used else 0
        value += unused * '0'
        value = bytes((int(value[i:i + 8], 2) for i in range(0, len(value), 8)))
    else:
        raise ASN1EncodeError('Unexpected type of bit string value')
    if named:
        while value and (not value[-1] & 1 << unused):
            unused += 1
            if unused == 8:
                value = value[:-1]
                unused = 0
    self.value = value
    self.unused = unused

def func(data):
    if len(data) < 2:
        raise ASN1DecodeError('Incomplete data')
    tag = data[0]
    asn1_class, constructed, tag = (tag >> 6, bool(tag & 32), tag & 31)
    offset = 1
    if tag == 31:
        tag = 0
        for b in data[offset:]:
            offset += 1
            if b < 128:
                tag |= b
                break
            else:
                tag |= b & 127
                tag <<= 7
        else:
            raise ASN1DecodeError('Incomplete tag')
    if offset >= len(data):
        raise ASN1DecodeError('Incomplete data')
    length = data[offset]
    offset += 1
    if length > 128:
        len_size = length & 127
        length = int.from_bytes(data[offset:offset + len_size], 'big')
        offset += len_size
    elif length == 128:
        raise ASN1DecodeError('Indefinite length not allowed')
    end = offset + length
    content = data[offset:end]
    if end > len(data):
        raise ASN1DecodeError('Incomplete data')
    if asn1_class == UNIVERSAL and tag in _der_class_by_tag:
        cls = _der_class_by_tag[tag]
        value = cls.decode(constructed, content)
    elif constructed:
        value = TaggedDERObject(tag, der_decode(content), asn1_class)
    else:
        value = RawDERObject(tag, content, asn1_class)
    return (value, end)

def func(hash_alg, passphrase, salt, count, key_size):
    if isinstance(passphrase, str):
        passphrase = passphrase.encode('utf-8')
    key = passphrase + salt
    for _ in range(count):
        key = hash_alg(key).digest()
    if len(key) <= key_size:
        return key + func(hash_alg, key + passphrase, salt, count, key_size - len(key))
    else:
        return key[:key_size]

def func(self, callback):
    _CallbackExceptionHelper.__init__(self)
    @wraps(callback)
    def wrapper(ssl, cdata):
        try:
            conn = Connection._reverse_mapping[ssl]
            if cdata != _ffi.NULL:
                data = _ffi.from_handle(cdata)
            else:
                data = None
            ocsp_ptr = _ffi.new('unsigned char **')
            ocsp_len = _lib.SSL_get_tlsext_status_ocsp_resp(ssl, ocsp_ptr)
            if ocsp_len < 0:
                ocsp_data = b''
            else:
                ocsp_data = _ffi.buffer(ocsp_ptr[0], ocsp_len)[:]
            valid = callback(conn, ocsp_data, data)
            return int(bool(valid))
        except Exception as e:
            self._problems.append(e)
            return -1
    self.callback = _ffi.callback('int (*)(SSL *, void *)', wrapper)

