def func(self, func_input):
    length = func_input.size()
    func, inv = self.get_function(length)
    try:
        index = self.interval_hook_for_size[length]
    except KeyError:
        self.interval_hook_for_size[length] = self._index_counter
        index = self._index_counter
        self._index_counter -= INTERVAL_DIFFERENCE
    lower_bound = index * PART
    upper_bound = lower_bound + PART
    cond = And(inv(func(func_input)) == func_input, ULE(symbol_factory.BitVecVal(lower_bound, 256), func(func_input)), ULT(func(func_input), symbol_factory.BitVecVal(upper_bound, 256)), URem(func(func_input), symbol_factory.BitVecVal(64, 256)) == 0)
    concrete_cond = symbol_factory.Bool(False)
    for key, keccak in self.concrete_hashes.items():
        if key.size() == func_input.size():
            hash_eq = And(func(func_input) == keccak, key == func_input)
            concrete_cond = Or(concrete_cond, hash_eq)
    return And(inv(func(func_input)) == func_input, Or(cond, concrete_cond))

def func(broker, port, username, password):
    import paho.mqtt.client as mqtt
    client = mqtt.Client()
    if username and password:
        client.username_pw_set(username, password)
    result = queue.Queue(maxsize=1)
    def on_connect(client_, userdata, flags, result_code):
        result.put(result_code == mqtt.CONNACK_ACCEPTED)
    client.on_connect = on_connect
    client.connect_async(broker, port)
    client.loop_start()
    try:
        return result.get(timeout=5)
    except queue.Empty:
        return False
    finally:
        client.disconnect()
        client.loop_stop()

