    event_collector = '{}{}:{}/services/collector/event'.format(uri_scheme, host, port)
    headers = {'Authorization': 'Splunk {}'.format(token)}
    def splunk_event_listener(event):
        state = event.data.get('new_state')
        if state is None:
            return
        try:
            _state = state_helper.state_as_number(state)
        except ValueError:
            _state = state.state
        json_body = [{'domain': state.domain, 'entity_id': state.object_id, 'attributes': dict(state.attributes), 'time': str(event.time_fired), 'value': _state, 'host': name}]
        try:
            payload = {'host': event_collector, 'event': json_body}
            requests.post(event_collector, data=json.dumps(payload), headers=headers, timeout=10)
        except requests.exceptions.RequestException as error:
            _LOGGER.exception('Error saving event to Splunk: %s', error)
    hass.bus.listen(EVENT_STATE_CHANGED, splunk_event_listener)
    return True

def func(self, var, default=None):
    return_value = None
    if var.startswith(SECRET_ENV_PREFIX):
        raise SecretEnvVarLocationError(var)
    env = get_invocation_context().env
    if var in env:
        return_value = env[var]
    elif default is not None:
        return_value = default
    if return_value is not None:
        compiling = True if hasattr(self.model, 'compiled') and getattr(self.model, 'compiled', False) is True else False
        if self.model and (not compiling):
            self.manifest.env_vars[var] = return_value if var in env else DEFAULT_ENV_PLACEHOLDER
            if self.model.file_id in self.manifest.files:
                source_file = self.manifest.files[self.model.file_id]
                if source_file.parse_file_type != 'schema':
                    source_file.env_vars.append(var)
        return return_value
    else:
        raise EnvVarMissingError(var)

