async def func(self, addr, port, family=socket.AF_INET, ssl=None, reconnect=True, initial=False):
    logger.debug(f'Starting to connect to {addr}:{port}')
    await self._disconnect_peers()
    if not initial:
        jitter = self._backoff * BACKOFF_JITTER
        min_backoff_value = max(0, self._backoff - jitter)
        max_backoff_value = self._backoff + jitter
        backoff_duration = random.uniform(min_backoff_value, max_backoff_value)
        if backoff_duration:
            logger.info(f'Waiting {backoff_duration:.1f} seconds before connection attempt')
            try:
                await asyncio.sleep(backoff_duration)
            except asyncio.CancelledError:
                return
        self._backoff = min(self._backoff_maximum, self._backoff + self._backoff / 2 + 1)
    _protocol = None
    try:
        _transport, _protocol = await self.loop.create_connection(self._protocol_factory, host=addr, port=port, ssl=ssl, family=family)
        self._backoff = 0
        self._connect_task = None
        self._running = True
        try:
            if self._on_started_handler:
                self._on_started_handler(self)
        except Exception as exc:
            logger.exception('Error in on_started callback method')
    except (ConnectionRefusedError, OSError) as exc:
        logger.error(f'Connection to {addr}:{port} was refused')
    except Exception as exc:
        logger.error(f'Unexpected error connecting to {addr}:{port}', exc_info=exc)
    if _protocol is None and reconnect:
        self._connect_task = self.loop.create_task(self._connect(addr=addr, port=port, family=family, ssl=ssl, reconnect=reconnect))
    else:
        self._backoff = 0

