    for retries in reversed(range(MAX_PATHS_QUERY_ATTEMPTS)):
        payload['iou'] = create_current_iou(config=service_config, token_network_address=token_network_address, one_to_n_address=one_to_n_address, our_address=our_address, privkey=privkey, chain_id=chain_id, block_number=current_block_number, offered_fee=offered_fee, scrap_existing_iou=scrap_existing_iou)
        try:
            return post_pfs_paths(url=url, token_network_address=token_network_address, payload=payload)
        except ServiceRequestIOURejected as error:
            code = error.error_code
            if retries == 0 or code in (PFSError.WRONG_IOU_RECIPIENT, PFSError.DEPOSIT_TOO_LOW):
                raise
            elif code in (PFSError.IOU_ALREADY_CLAIMED, PFSError.IOU_EXPIRED_TOO_EARLY):
                scrap_existing_iou = True
            elif code == PFSError.INSUFFICIENT_SERVICE_PAYMENT:
                if offered_fee < service_config['pathfinding_max_fee']:
                    offered_fee = service_config['pathfinding_max_fee']
                else:
                    raise
            log.info(f'PFS rejected our IOU, reason: {error}. Attempting again.')
    return (list(), None)

def func(url):
    try:
        creds_re = re.compile('//(.*)@')
        creds = creds_re.findall(url)[0]
        user_password = creds.split(':')
        baseurl = url.replace(creds + '@', '')
        tokenurl = baseurl.split('rest/')[0] + 'tokens?username=%s&password=%s' % (user_password[0], user_password[1])
        token = urllib.request.urlopen(tokenurl, None, 15).read()
        return baseurl + 'token=' + str(token, 'utf-8')
    except:
        print(url)
        traceback.print_exc(file=sys.stdout)
    return None

