def func(exec_name, args, logger):
    hidden_args = hide_args(args, ['--cities-connection-string', '--connection-string'])
    log = 'Launching ' + exec_name + ' ' + ' '.join(hidden_args)
    logger.info(re.sub('password=\\w+', 'password=xxxxxxxxx', log))
    args.insert(0, exec_name)
    proc = subprocess.Popen(args, stderr=subprocess.PIPE, stdout=subprocess.PIPE, close_fds=True)
    traces = ''
    try:
        make_async(proc.stderr)
        make_async(proc.stdout)
        while True:
            select.select([proc.stdout, proc.stderr], [], [])
            try:
                for pipe in (proc.stdout, proc.stderr):
                    log_pipe = read_async(pipe)
                    if log_pipe:
                        logs, line = parse_log(log_pipe.decode('utf-8', errors='replace'))
                        for l in logs:
                            logger.log(l.level, l.msg)
                            traces += '##  {}  ##'.format(l.msg)
            except Exception as e:
                logger.error('error in forwarding logs but process continuing: {}'.format(e))
            if proc.poll() is not None:
                break
    finally:
        proc.stdout.close()
        proc.stderr.close()
    return (proc.returncode, traces)

def func(policy):
    if not policy:
        def apply_policy_deny_all(entity_id, keys):
            return False
        return apply_policy_deny_all
    if policy is True:
        def apply_policy_allow_all(entity_id, keys):
            return True
        return apply_policy_allow_all
    assert isinstance(policy, dict)
    domains = policy.get(ENTITY_DOMAINS)
    entity_ids = policy.get(ENTITY_ENTITY_IDS)
    funcs = []
    if isinstance(entity_ids, bool):
        def apply_entity_id_policy(entity_id, keys):
            return entity_ids
        return apply_entity_id_policy
    if entity_ids is not None:
        def allowed_entity_id(entity_id, keys):
            return entity_ids.get(entity_id)
        funcs.append(allowed_entity_id)
    if isinstance(domains, bool):
        def allowed_domain(entity_id, keys):
            return domains
        funcs.append(allowed_domain)
    elif domains is not None:
        def allowed_domain(entity_id, keys):
            domain = entity_id.split('.', 1)[0]
            return domains.get(domain)
        funcs.append(allowed_domain)
    if not funcs:
        def apply_policy_deny_all_2(entity_id, keys):
            return False
        return apply_policy_deny_all_2
    if len(funcs) == 1:
        func = funcs[0]
        def apply_policy_func(entity_id, keys):
            return func(entity_id, keys) is True
        return apply_policy_func
    def apply_policy_funcs(entity_id, keys):
        for func in funcs:
            result = func(entity_id, keys)
            if result is not None:
                return result
        return False
    return apply_policy_funcs

def func(job_order_object, args, process, loader, stdout, print_input_deps=False, relative_deps='primary', make_fs_access=StdFsAccess, input_basedir='', secret_store=None, input_required=True, runtime_context=None):
    secrets_req, _ = process.get_requirement('http://commonwl.org/cwltool#Secrets')
    if job_order_object is None:
        namemap = {}
        records = []
        toolparser = generate_parser(argparse.ArgumentParser(prog=args.workflow), process, namemap, records, input_required, loader.fetcher.urljoin, file_uri(os.getcwd()) + '/')
        if args.tool_help:
            toolparser.print_help(stdout)
            exit(0)
        cmd_line = vars(toolparser.parse_args(args.job_order))
        for record_name in records:
            record = {}
            record_items = {k: v for k, v in cmd_line.items() if k.startswith(record_name)}
            for key, value in record_items.items():
                record[key[len(record_name) + 1:]] = value
                del cmd_line[key]
            cmd_line[str(record_name)] = record
        if 'job_order' in cmd_line and cmd_line['job_order']:
            try:
                job_order_object = cast(CWLObjectType, loader.resolve_ref(cmd_line['job_order'])[0])
            except Exception:
                _logger.exception('Failed to resolv job_order: %s', cmd_line['job_order'])
                exit(1)
        else:
            job_order_object = {jobloader_id_name: args.workflow}
        del cmd_line['job_order']
        job_order_object.update({namemap[k]: v for k, v in cmd_line.items()})
        if secret_store and secrets_req:
            secret_store.store([shortname(sc) for sc in cast(List[str], secrets_req['secrets'])], job_order_object)
        if _logger.isEnabledFor(logging.DEBUG):
            _logger.debug('Parsed job order from command line: %s', json_dumps(job_order_object, indent=4, default=str))
    for inp in process.tool['inputs']:
        if 'default' in inp and (not job_order_object or shortname(inp['id']) not in job_order_object):
            if not job_order_object:
                job_order_object = {}
            job_order_object[shortname(inp['id'])] = inp['default']
    def path_to_loc(p):
        if 'location' not in p and 'path' in p:
            p['location'] = p['path']
            del p['path']
    ns = {}
    ns.update(cast(ContextType, job_order_object.get('$namespaces', {})))
    ns.update(cast(ContextType, process.metadata.get('$namespaces', {})))
    ld = Loader(ns)
    def expand_formats(p):
        if 'format' in p:
            p['format'] = ld.expand_url(cast(str, p['format']), '')
    visit_class(job_order_object, ('File', 'Directory'), path_to_loc)
    visit_class(job_order_object, ('File',), functools.partial(add_sizes, make_fs_access(input_basedir)))
    visit_class(job_order_object, ('File',), expand_formats)
    adjustDirObjs(job_order_object, trim_listing)
    normalizeFilesDirs(job_order_object)
    if print_input_deps:
        if not runtime_context:
            raise RuntimeError('runtime_context is required for print_input_deps.')
        runtime_context.toplevel = True
        builder = process._init_job(job_order_object, runtime_context)
        builder.loadListing = 'no_listing'
        builder.bind_input(process.inputs_record_schema, job_order_object, discover_secondaryFiles=True)
        basedir = None
        uri = cast(str, job_order_object[jobloader_id_name])
        if uri == args.workflow:
            basedir = os.path.dirname(uri)
            uri = ''
        printdeps(job_order_object, loader, stdout, relative_deps, uri, basedir=basedir, nestdirs=False)
        exit(0)
    if secret_store and secrets_req:
        secret_store.store([shortname(sc) for sc in cast(List[str], secrets_req['secrets'])], job_order_object)
    if 'cwl:tool' in job_order_object:
        del job_order_object['cwl:tool']
    if jobloader_id_name in job_order_object:
        del job_order_object[jobloader_id_name]
    return job_order_object

def func(self, database_handler):
    default_source = self.source if self.operation == DatabaseOperation.delete else None
    obj = None
    if self.object_text:
        try:
            object_text = self.object_text.strip()
            obj = rpsl_object_from_text(object_text, strict_validation=False, default_source=default_source)
            if self.strict_validation_key_cert and obj.__class__ == RPSLKeyCert:
                obj = rpsl_object_from_text(object_text, strict_validation=True, default_source=default_source)
        except UnknownRPSLObjectClassException as exc:
            if not self.object_class_filter or exc.rpsl_object_class.lower() in self.object_class_filter:
                logger.info(f'Ignoring NRTM operation {str(self)}: {exc}')
            return False
        self.rpsl_pk = obj.pk()
        self.object_class = obj.rpsl_object_class.lower()
    if not self.object_class:
        raise RuntimeError('NRTMOperation called with neither object_text nor object_class')
    if self.object_class_filter and self.object_class.lower() not in self.object_class_filter:
        return False
    if obj and obj.messages.errors():
        errors = '; '.join(obj.messages.errors())
        logger.critical(f'Parsing errors occurred while processing NRTM operation {str(self)}. This operation is ignored, causing potential data inconsistencies. A new operation for this update, without errors, will still be processed and cause the inconsistency to be resolved. Parser error messages: {errors}; original object text follows:\n{self.object_text}')
        database_handler.record_mirror_error(self.source, f'Parsing errors: {obj.messages.errors()}, original object text follows:\n{self.object_text}')
        return False
    if obj and 'source' in obj.parsed_data and (obj.parsed_data['source'].upper() != self.source):
        msg = f'Incorrect source in NRTM object: stream has source {self.source}, found object with source {obj.source()} in operation {self.origin_identifier}/{self.operation.value}/{obj.pk()}. This operation is ignored, causing potential data inconsistencies.'
        database_handler.record_mirror_error(self.source, msg)
        logger.critical(msg)
        return False
    if obj and self.operation == DatabaseOperation.add_or_update:
        if self.rpki_aware and obj.is_route and obj.prefix and obj.asn_first:
            roa_validator = SingleRouteROAValidator(database_handler)
            obj.rpki_status = roa_validator.validate_route(obj.prefix, obj.asn_first, obj.source())
        scope_validator = ScopeFilterValidator()
        obj.scopefilter_status, _ = scope_validator.validate_rpsl_object(obj)
        database_handler.upsert_rpsl_object(obj, JournalEntryOrigin.mirror, source_serial=self.serial)
    elif self.operation == DatabaseOperation.delete:
        database_handler.delete_rpsl_object(source=self.source, rpsl_pk=self.rpsl_pk, object_class=self.object_class, origin=JournalEntryOrigin.mirror, source_serial=self.serial)
    log = f'Completed NRTM operation {str(self)}/{self.object_class}/{self.rpsl_pk}'
    if obj and self.rpki_aware and obj.is_route:
        log += f', RPKI status {obj.rpki_status.value}'
    logger.info(log)
    return True

def func(conn, table_name, column_list, s3_uri, aws_iam_role, data_format=None, format_option=None, file_compression=None, dry_run=False):
    credentials = 'aws_iam_role={}'.format(aws_iam_role)
    data_format_parameters = determine_data_format_parameters(data_format, format_option, file_compression)
    compupdate = etl.config.get_config_value('arthur_settings.redshift.relation_column_encoding', 'ON')
    if compupdate == 'AUTO':
        compupdate = 'OFF'
    copy_stmt = "\n        -- arthur.copy: {table.identifier}\n        COPY {table} (\n            {columns}\n        )\n        FROM %s\n        CREDENTIALS %s MANIFEST\n        {data_format_parameters}\n        TIMEFORMAT AS 'auto'\n        DATEFORMAT AS 'auto'\n        TRUNCATECOLUMNS\n        STATUPDATE OFF\n        COMPUPDATE {compupdate}\n        ".format(table=table_name, columns=join_with_double_quotes(column_list), data_format_parameters=data_format_parameters, compupdate=compupdate)
    if dry_run:
        logger.info("Dry-run: Skipping copying data into '%s' using '%s'", table_name.identifier, s3_uri)
        etl.db.skip_query(conn, copy_stmt, (s3_uri, credentials))
        return
    logger.info("Copying data into '%s' using '%s'", table_name.identifier, s3_uri)
    try:
        with log_load_error(conn):
            etl.db.execute(conn, copy_stmt, (s3_uri, credentials))
    except psycopg2.InternalError as exc:
        if exc.pgcode == 'XX000':
            raise ETLRuntimeError(exc) from exc
        raise TransientETLError(exc) from exc

def func(weights_uri, unzip=False):
    if weights_uri is None:
        logging.info('No weights to be fetched for this model.')
        return
    hash_digest = sha256_hash(weights_uri)
    local_path = home_directory_path(FOLDER, hash_digest)
    exists_locally = path_exists(local_path)
    filename = _filename_from_uri(weights_uri)
    file_path = os.path.join(local_path, filename)
    if exists_locally:
        logging.info('Weights already stored locally.')
