    type_name = 'Full'
    for folder in folders:
        if folder not in self.config.get(Setting.EXCLUDE_FOLDERS):
            request_info['folders'].append(folder)
        else:
            type_name = 'Partial'
    for addon in addons:
        if addon not in self.config.get(Setting.EXCLUDE_ADDONS):
            request_info['addons'].append(addon)
