def func(request, response):
    if request.method == 'OPTIONS':
        if 'www2' in request.headers['Origin']:
            return (400, [], 'CORS preflight rejected for www2')
        return ([('Content-Type', 'text/plain'), ('Access-Control-Allow-Origin', '*'), ('Access-Control-Allow-Methods', 'post'), ('Access-Control-Allow-Headers', 'Content-Type')], 'CORS allowed')
    op = request.GET.first('op')
    key = request.GET.first('reportID')
    if op == 'retrieve_report':
        try:
            timeout = float(request.GET.first('timeout'))
        except:
            timeout = 0.5
        try:
            min_count = int(request.GET.first('min_count'))
        except:
            min_count = 1
        return ([('Content-Type', 'application/json')], retrieve_from_stash(request, key, timeout, min_count, '[]'))
    new_reports = json.loads(request.body)
    for report in new_reports:
        report['metadata'] = {'content_type': request.headers['Content-Type']}
    with request.server.stash.lock:
        reports = request.server.stash.take(key=key)
        if reports is None:
            reports = []
        reports.extend(new_reports)
        request.server.stash.put(key=key, value=reports)
    return ([('Content-Type', 'text/plain')], 'Recorded report')

def func(self, data, deserialize=True, secure=False):
    if secure:
        if 'state' in data:
            raise StateUpdateProhibitedError()
        for protected in self.schema.__protected_fields__:
            if protected in data.keys():
                raise UnprocessableError('%s is not allowed to be set in this context' % protected)
        for fn, fo in self.schema.__dataclass_fields__.items():
            if fn in data.keys() and (not fo.metadata.get('initializable', True)):
                raise UnprocessableError('%s is not allowed to be set in this context' % fn)
    data = self.schema.validate(self.request, data, deserialize=deserialize, context=self)
    self.before_create(data)
    identifier = self.app.get_default_identifier(self.schema, data, self.request)
    if identifier and self.get(identifier):
        raise self.exist_exc(identifier)
    data = self.storage.set_schema_defaults(data)
    for fname, field in self.schema.__dataclass_fields__.items():
        if data[fname] is not None:
            continue
        dc_default_factory = field.default_factory
        if not isinstance(dc_default_factory, dataclasses._MISSING_TYPE):
            data[fname] = dc_default_factory()
        if data[fname] is not None:
            continue
        default_factory = field.metadata.get('default_factory', None)
        if default_factory:
            data[fname] = default_factory(self, self.request)
    unique_constraint = getattr(self.schema, '__unique_constraint__', None)
    if unique_constraint:
        unique_search = []
        msg = []
        for c in unique_constraint:
            unique_search.append(rulez.field[c] == data[c])
            msg.append(f'{c}=({data[c]})')
        if self.search(rulez.and_(*unique_search)):
            raise self.exist_exc(' '.join(msg))
    self.update_computed_fields(data)
    obj = self._create(data)
    obj.set_initial_state()
    dispatch = self.request.app.dispatcher(signals.OBJECT_CREATED)
    dispatch.dispatch(self.request, obj)
    obj.after_created()
    obj.save()
    return obj

def func(arg):
    def with_arg(view):
        @functools.wraps(view)
        async def wrapper(**kwargs):
            request = kwargs['request']
            c = request.app.config.recaptcha
            response = None
            if RECAPTCHA_FIELD in request:
                response = request[RECAPTCHA_FIELD]
            else:
                for v in kwargs.values():
                    if isinstance(v, dict) and RECAPTCHA_FIELD in v:
                        response = v.pop(RECAPTCHA_FIELD)
                        break
            if not c.active:
                return await view(**kwargs)
            if response:
                async with aiohttp.ClientSession() as client:
                    async with client.post(c.url, data={'secret': c.secret, 'response': response}) as r:
                        if r.status == aiohttp.web.HTTPOk.status_code:
                            data = await r.json()
                            if data['success']:
                                return await view(**kwargs)
            raise HTTPNotAcceptable(reason='Wrong recaptcha')
        return wrapper
    if not callable(arg):
        return with_arg
    return with_arg(arg)

def func(self):
    if self.user is None:
        raise HTTPUnauthorized('Authentication required', headers=[('WWW-Authenticate', 'Basic realm="TinyOWS"')])
    operation = self.lower_params.get('request')
    typenames = {normalize_typename(self.lower_params['typename'])} if 'typename' in self.lower_params else set()
    method = self.request.method
    if method == 'POST':
        try:
            operation, typenames_post = self._parse_body(self.request.body)
        except Exception:
            LOG.exception('Error while parsing POST request body')
            raise HTTPBadRequest('Error parsing the request (see logs for more details)')
        typenames = typenames.union(typenames_post)
    if operation is None or operation == '':
        operation = 'getcapabilities'
    if operation == 'describefeaturetype':
        if len(typenames) != 1:
            raise HTTPBadRequest('Exactly one type-name must be given for DescribeFeatureType requests')
    if not self._is_allowed(typenames):
        raise HTTPForbidden('No access rights for at least one of the given type-names')
    use_cache = method == 'GET' and operation in ('getcapabilities', 'describefeaturetype')
    cache_control = Cache.PRIVATE if use_cache else Cache.PRIVATE_NO
    url = Url(self.settings.get('tinyows_url'))
    response = self._proxy_callback(operation, cache_control, url=url, params=dict(self.request.params), cache=use_cache, headers=self._get_headers(), body=self.request.body)
    return response

def func(validator, request, operation):
    security_list = get_security_list(validator, operation)
    if not security_list:
        return pmap()
    has_empty_security = {} in security_list
    if has_empty_security:
        security_list.remove({})
        security_list.append({})
    for item in security_list:
        data = {key: get_security_data(validator, request, key) for key in item}
        if all((value for value in data.values())):
            return pmap(data)
    if len(security_list) == 1 and len(security_list[0]) == 1:
        scheme_name = list(security_list[0].keys())[0]
        if is_basic_auth_security_scheme(validator, scheme_name):
            raise BasicSecurityError()
    raise SecurityError()

def func(ctx, name, data, method_verb):
    method_verb = InferenceVerb(method_verb)
    try:
        namespace = get_kubectl_current_context_namespace()
        inference_instance = Run.get(name=name, namespace=namespace)
        if not inference_instance:
            handle_error(user_msg=Texts.INSTANCE_NOT_EXISTS_ERROR_MSG.format(name=name))
            exit(1)
        if not inference_instance.state == RunStatus.RUNNING:
            handle_error(user_msg=Texts.INSTANCE_NOT_RUNNING_ERROR_MSG.format(name=name, running_code=RunStatus.RUNNING.value))
            exit(1)
        inference_instance_url = get_inference_instance_url(inference_instance=inference_instance)
        stream_url = f'{inference_instance_url}:{method_verb.value}'
    except Exception:
        handle_error(logger, Texts.INSTANCE_GET_FAIL_ERROR_MSG.format(name=name), Texts.INSTANCE_GET_FAIL_ERROR_MSG.format(name=name), add_verbosity_msg=ctx.obj.verbosity == 0)
        exit(1)
    try:
        with open(data, 'r', encoding='utf-8') as data_file:
            stream_data = json.load(data_file)
    except (json.JSONDecodeError, IOError):
        handle_error(logger, Texts.JSON_LOAD_ERROR_MSG.format(data=data), Texts.JSON_LOAD_ERROR_MSG.format(data=data))
        exit(1)
    try:
        api_key = get_api_key()
        headers = {'Authorization': api_key, 'Accept': 'application/json', 'Content-Type': 'application/json'}
        with spinner(text=Texts.WAITING_FOR_RESPONSE_MSG):
            stream_response = requests.post(stream_url, data=json.dumps(stream_data), verify=False, headers=headers)
        stream_response.raise_for_status()
        click.echo(stream_response.text)
    except Exception as e:
        error_msg = Texts.INFERENCE_OTHER_ERROR_MSG.format(exception=e)
        if hasattr(e, 'response'):
            error_msg += Texts.INFERENCE_ERROR_RESPONSE_MSG.format(response_text=e.response.text)
        handle_error(logger, error_msg, error_msg)
        exit(1)

