def func(self, address, params=None):
    params = params or []
    position, length, mappings = (0, 1, [])
    try:
        if params[0] == 'mapping':
            if len(params) < 3:
                raise CriticalError('Invalid number of parameters.')
            position = int(params[1])
            position_formatted = zpad(int_to_big_endian(position), 32)
            for i in range(2, len(params)):
                key = bytes(params[i], 'utf8')
                key_formatted = rzpad(key, 32)
                mappings.append(int.from_bytes(sha3(key_formatted + position_formatted), byteorder='big'))
            length = len(mappings)
            if length == 1:
                position = mappings[0]
        else:
            if len(params) >= 4:
                raise CriticalError('Invalid number of parameters.')
            if len(params) >= 1:
                position = int(params[0])
            if len(params) >= 2:
                length = int(params[1])
            if len(params) == 3 and params[2] == 'array':
                position_formatted = zpad(int_to_big_endian(position), 32)
                position = int.from_bytes(sha3(position_formatted), byteorder='big')
    except ValueError:
        raise CriticalError('Invalid storage index. Please provide a numeric value.')
    outtxt = []
    try:
        if length == 1:
            outtxt.append('{}: {}'.format(position, self.eth.eth_getStorageAt(address, position)))
        elif len(mappings) > 0:
            for i in range(0, len(mappings)):
                position = mappings[i]
                outtxt.append('{}: {}'.format(hex(position), self.eth.eth_getStorageAt(address, position)))
        else:
            for i in range(position, position + length):
                outtxt.append('{}: {}'.format(hex(i), self.eth.eth_getStorageAt(address, i)))
    except FileNotFoundError as e:
        raise CriticalError('IPC error: ' + str(e))
    except ConnectionError:
        raise CriticalError('Could not connect to RPC server. Make sure that your node is running and that RPC parameters are set correctly.')
    return '\n'.join(outtxt)

