def func(ious, claim_cost_rdn, one_to_n_contract, web3, database):
    unchecked_txs = []
    skipped = 0
    for iou in ious:
        claim = one_to_n_contract.functions.claim(sender=iou.sender, receiver=iou.receiver, amount=iou.amount, claimable_until=iou.claimable_until, signature=iou.signature)
        transferrable = claim.call()
        if transferrable < claim_cost_rdn:
            print('Not enough user deposit to claim profitably for', iou)
            skipped += 1
            continue
        tx_hash = claim.transact()
        unchecked_txs.append((tx_hash, iou))
    failures = 0
    while unchecked_txs:
        for tx_hash, iou in unchecked_txs.copy():
            try:
                receipt = web3.eth.get_transaction_receipt(tx_hash)
            except TransactionNotFound:
                continue
            unchecked_txs.remove((tx_hash, iou))
            if receipt['status'] == 1:
                print(f'Successfully claimed {iou}.')
                iou.claimed = True
                database.upsert_iou(iou)
            else:
                print(f'Claiming {iou} failed!')
                failures += 1
    return (skipped, failures)

def func(self, playbook, timeout, ansible_version, success=None, phase=None, index=None):
    if self.executor_server.verbose:
        verbose = '-vvv'
    else:
        verbose = '-v'
    cmd = [self.executor_server.ansible_manager.getAnsibleCommand(ansible_version), verbose, playbook.path]
    if playbook.secrets_content:
        cmd.extend(['-e', '@' + playbook.secrets])
    cmd.extend(['-e', '@' + self.jobdir.extra_vars])
    if success is not None:
        cmd.extend(['-e', 'zuul_success=%s' % str(bool(success))])
    if phase:
        cmd.extend(['-e', 'zuul_execution_phase=%s' % phase])
    if index is not None:
        cmd.extend(['-e', 'zuul_execution_phase_index=%s' % index])
    cmd.extend(['-e', 'zuul_execution_trusted=%s' % str(playbook.trusted)])
    cmd.extend(['-e', 'zuul_execution_canonical_name_and_path=%s' % playbook.canonical_name_and_path])
    cmd.extend(['-e', 'zuul_execution_branch=%s' % str(playbook.branch)])
    if self.executor_variables_file is not None:
        cmd.extend(['-e@%s' % self.executor_variables_file])
    self.emitPlaybookBanner(playbook, 'START', phase)
    result, code = self.runAnsible(cmd, timeout, playbook, ansible_version, cleanup=phase == 'cleanup')
    self.log.debug('Ansible complete, result %s code %s' % (self.RESULT_MAP[result], code))
    if self.executor_server.statsd:
        base_key = 'zuul.executor.{hostname}.phase.{phase}'
        self.executor_server.statsd.incr(base_key + '.{result}', result=self.RESULT_MAP[result], phase=phase or 'unknown')
    self.emitPlaybookBanner(playbook, 'END', phase, result=result)
    return (result, code)

