def func(gpg_obj, secrets_path, obj, verify=True, **kwargs):
    def sub_reveal_data(data):
        _reveal_gpg_replace = partial(reveal_gpg_replace, gpg_obj, secrets_path, verify=verify, **kwargs)
        return re.sub(SECRET_TOKEN_TAG_PATTERN, _reveal_gpg_replace, data)
    if isinstance(obj, dict):
        for k, v in obj.items():
            obj[k] = func(gpg_obj, secrets_path, v, verify, **kwargs)
    elif isinstance(obj, list):
        obj = [func(gpg_obj, secrets_path, item, verify, **kwargs) for item in obj]
    elif isinstance(obj, string_types):
        obj = sub_reveal_data(obj)
    return obj

