def func(self, url, method, params, context=None):
    arg_hash = {'method': method, 'params': params, 'version': '1.1', 'id': str(_random.random())[2:]}
    if context:
        if type(context) is not dict:
            raise ValueError('context is not type dict as required.')
        arg_hash['context'] = context
    body = _json.dumps(arg_hash, cls=_JSONObjectEncoder)
    ret = _requests.post(url, data=body, headers=self._headers, timeout=self.timeout, verify=not self.trust_all_ssl_certificates)
    ret.encoding = 'utf-8'
    if ret.status_code == 500:
        if ret.headers.get(_CT) == _AJ:
            err = ret.json()
            if 'error' in err:
                raise ServerError(**err['error'])
            else:
                raise ServerError('Unknown', 0, ret.text)
        else:
            raise ServerError('Unknown', 0, ret.text)
    if not ret.ok:
        ret.raise_for_status()
    resp = ret.json()
    if 'result' not in resp:
        raise ServerError('Unknown', 0, 'An unknown server error occurred')
    if not resp['result']:
        return
    if len(resp['result']) == 1:
        return resp['result'][0]
    return resp['result']

