def func(self, http, token):
    logger.info('Revoking token')
    query_params = {'token': token}
    token_revoke_uri = _helpers.update_query_params(self.revoke_uri, query_params)
    resp, content = transport.request(http, token_revoke_uri)
    if resp.status == http_client.METHOD_NOT_ALLOWED:
        body = urllib.parse.urlencode(query_params)
        resp, content = transport.request(http, token_revoke_uri, method='POST', body=body)
    if resp.status == http_client.OK:
        self.invalid = True
    else:
        error_msg = 'Invalid response {0}.'.format(resp.status)
        try:
            d = json.loads(_helpers._from_bytes(content))
            if 'error' in d:
                error_msg = d['error']
        except (TypeError, ValueError):
            pass
        raise TokenRevokeError(error_msg)
    if self.store:
        self.store.delete()

def func(self, address, params=None):
    params = params or []
    position, length, mappings = (0, 1, [])
    try:
        if params[0] == 'mapping':
            if len(params) < 3:
                raise CriticalError('Invalid number of parameters.')
            position = int(params[1])
            position_formatted = utils.zpad(utils.int_to_big_endian(position), 32)
            for i in range(2, len(params)):
                key = bytes(params[i], 'utf8')
                key_formatted = utils.rzpad(key, 32)
                mappings.append(int.from_bytes(utils.sha3(key_formatted + position_formatted), byteorder='big'))
            length = len(mappings)
            if length == 1:
                position = mappings[0]
        else:
            if len(params) >= 4:
                raise CriticalError('Invalid number of parameters.')
            if len(params) >= 1:
                position = int(params[0])
            if len(params) >= 2:
                length = int(params[1])
            if len(params) == 3 and params[2] == 'array':
                position_formatted = utils.zpad(utils.int_to_big_endian(position), 32)
                position = int.from_bytes(utils.sha3(position_formatted), byteorder='big')
    except ValueError:
        raise CriticalError('Invalid storage index. Please provide a numeric value.')
    outtxt = []
    try:
        if length == 1:
            outtxt.append('{}: {}'.format(position, self.eth.eth_getStorageAt(address, position)))
        elif len(mappings) > 0:
            for i in range(0, len(mappings)):
                position = mappings[i]
                outtxt.append('{}: {}'.format(hex(position), self.eth.eth_getStorageAt(address, position)))
        else:
            for i in range(position, position + length):
                outtxt.append('{}: {}'.format(hex(i), self.eth.eth_getStorageAt(address, i)))
    except FileNotFoundError as e:
        raise CriticalError('IPC error: ' + str(e))
    except ConnectionError:
        raise CriticalError('Could not connect to RPC server. Make sure that your node is running and that RPC parameters are set correctly.')
    return '\n'.join(outtxt)

def func(params):
    if isinstance(params.curve.model, ShortWeierstrassModel):
        if params.order * params.cofactor % 2 != 0:
            return None
        k = FF(params.curve.prime)
        expr = sympify('x^3 + a * x + b', evaluate=False)
        expr = expr.subs('a', k(int(params.curve.parameters['a'])))
        expr = expr.subs('b', k(int(params.curve.parameters['b'])))
        poly = Poly(expr, symbols('x'), domain=k)
        roots = poly.ground_roots()
        if not roots:
            return None
        x = Mod(int(next(iter(roots.keys()))), params.curve.prime)
        return Point(AffineCoordinateModel(params.curve.model), x=x, y=Mod(0, params.curve.prime))
    elif isinstance(params.curve.model, MontgomeryModel):
        return Point(AffineCoordinateModel(params.curve.model), x=Mod(0, params.curve.prime), y=Mod(0, params.curve.prime))
    else:
        raise NotImplementedError

