    return result

def func(self, expression):
    str_eval = ''
    easm_code = None
    tokens = re.split('\\s+(and|or|not)\\s+', expression, re.IGNORECASE)
    for token in tokens:
        if token in ('and', 'or', 'not'):
            str_eval += ' ' + token + ' '
            continue
        m = re.match('^code#([a-zA-Z0-9\\s,\\[\\]]+)#', token)
        if m:
            if easm_code is None:
                easm_code = self.get_easm()
            code = m.group(1).replace(',', '\\n')
            str_eval += '"' + code + '" in easm_code'
            continue
        m = re.match('^func#([a-zA-Z0-9\\s_,(\\\\)\\[\\]]+)#$', token)
        if m:
            sign_hash = '0x' + utils.sha3(m.group(1))[:4].hex()
            str_eval += '"' + sign_hash + '" in self.disassembly.func_hashes'
            continue
    return eval(str_eval.strip())

async def func(self, sock, protocol_factory, ssl, server_hostname, server_side=False, ssl_handshake_timeout=None):
    sock.setblocking(False)
    protocol = protocol_factory()
    waiter = self.create_future()
    if ssl:
        sslcontext = None if isinstance(ssl, bool) else ssl
        transport = self._make_ssl_transport(sock, protocol, sslcontext, waiter, server_side=server_side, server_hostname=server_hostname, ssl_handshake_timeout=ssl_handshake_timeout)
    else:
        transport = self._make_socket_transport(sock, protocol, waiter)
    try:
        await waiter
    except:
        transport.close()
        raise
    return (transport, protocol)

