def func(op, request_data):
    security_types = set((definition.type for security_requirement in op.security_requirements for definition in itervalues(security_requirement.security_definitions)))
    if 'apiKey' in security_types:
        matched_security_indexes = []
        for security_index, security_params_list in enumerate(op.security_requirements):
            if all([request_data.get(security_param.name) is not None for security_param in security_params_list]):
                matched_security_indexes.append(security_index)
        if len(matched_security_indexes) == 0:
            raise SwaggerSecurityValidationError('No security definition used.')
        if len(matched_security_indexes) > 1:
            matched_security_definitions = sorted((set(security) for index, security in enumerate(op.acceptable_security_definition_combinations) if index in matched_security_indexes), key=len, reverse=True)
            all_same_length = len(matched_security_definitions[0]) == len(matched_security_definitions[-1])
            exists_superset = all((matched_security_definitions[0].issuperset(security_definition) for security_definition in matched_security_definitions))
            if all_same_length or not exists_superset:
                raise SwaggerSecurityValidationError('More than one security definition is in use at the same time ({0})'.format(', '.join((str(security) for index, security in enumerate(op.acceptable_security_definition_combinations) if index in matched_security_indexes))))

async def func(self, factory, tls_ctx):
    if self._fastest:
        try:
            return await open_connection(self._fastest, host=self.host, factory=factory, tls_ctx=tls_ctx)
        except asyncio.CancelledError:
            raise
        except Exception:
            self._fastest = None
    coros = {record: asyncio.ensure_future(open_connection(record, host=self.host, factory=factory, tls_ctx=tls_ctx)) for record in self.results}
    def read_result():
        for k, v in coros.items():
            try:
                return (k, v.result())
            except Exception:
                continue
        return None
    pending = set(coros.values())
    try:
        while len(pending) > 0:
            _, pending = await asyncio.wait(pending, return_when=asyncio.FIRST_COMPLETED)
            result = read_result()
            if result:
                record, (transport, protocol) = result
                self._fastest = record
                return (transport, protocol)
    finally:
        if coros:
            for coro in coros.values():
                coro.cancel()
            await asyncio.wait(set(coros.values()), return_when=asyncio.ALL_COMPLETED)
    raise exceptions.UnresolvableHost(f'{self.host}:{self.port} is not reachable.')

