        field_value = rest[:n]
        if rest[n:n + 1] != b'|':
            raise ValueError('malformed v2 signed value field')
        rest = rest[n + 1:]
        return (field_value, rest)
    rest = value[2:]
    key_version, rest = _consume_field(rest)
    timestamp, rest = _consume_field(rest)
    name_field, rest = _consume_field(rest)
    value_field, passed_sig = _consume_field(rest)
    return (int(key_version), timestamp, name_field, value_field, passed_sig)

def func(graph, edge_attr=None, node_attr=None, iterations=3, digest_size=16):
    def weisfeiler_lehman_step(G, labels, edge_attr=None):
        new_labels = {}
        for node in G.nodes():
            label = _neighborhood_aggregate(G, node, labels, edge_attr=edge_attr)
            new_labels[node] = _hash_label(label, digest_size)
        return new_labels
    node_labels = _init_node_labels(graph, edge_attr, node_attr)
    subgraph_hash_counts = []
    for _ in range(iterations):
        node_labels = weisfeiler_lehman_step(graph, node_labels, edge_attr=edge_attr)
        counter = Counter(node_labels.values())
        subgraph_hash_counts.extend(sorted(counter.items(), key=lambda x: x[0]))
    return _hash_label(str(tuple(subgraph_hash_counts)), digest_size)

def func(location=None):
    global _reasons_data
    if _reasons_data is not None:
        return _reasons_data
    if _reasons_data == 'LOAD FAILED':
        raise Exception('Previous load of reasons data failed, not trying again until _reasons_data is cleared by setting it to None')
    if location is None:
        location = os.environ.get('REASONS_GS_URL', DEFAULT_REASONS_GS_URL)
    if location is None:
        raise ValueError('Must pass location or set env var REASONS_GS_URL')
    blob = None
    try:
        bucket_name = location.strip('gs://').split('/')[0]
