        raise Exception(f'Could not get resons file from {location}')
    try:
        with blob.open('r') as fp:
            _reasons_data = json.load(fp)
            return _reasons_data
    except Exception as ex:
        _reasons_data = 'LOAD FAILED'
        raise ex

