def func(key, ip):
    if ip.version != 4:
        raise ValueError('IPv6 supplied to IPv4 function.')
    k = [int(x) for x in key]
    try:
        state = [int(x) for x in ip.exploded.split('.')]
    except ValueError:
        raise
    try:
        state = xor4(state, k[:4])
        state = permute_fwd(state)
        state = xor4(state, k[4:8])
        state = permute_fwd(state)
        state = xor4(state, k[8:12])
        state = permute_fwd(state)
        state = xor4(state, k[12:16])
    except IndexError:
        raise
    return '.'.join((str(x) for x in state))

def func(cls, auth_header, encoding='latin1'):
    try:
        auth_type, encoded_credentials = auth_header.split(' ', 1)
    except ValueError:
        raise ValueError('Could not parse authorization header.')
    if auth_type.lower() != 'basic':
        raise ValueError('Unknown authorization method %s' % auth_type)
    try:
        decoded = base64.b64decode(encoded_credentials.encode('ascii'), validate=True).decode(encoding)
    except binascii.Error:
        raise ValueError('Invalid base64 encoding.')
    try:
        username, password = decoded.split(':', 1)
    except ValueError:
        raise ValueError('Invalid credentials.')
    return cls(username, password, encoding=encoding)

