    except vol.Invalid as err:
        result.add_error(err, CONF_CORE, core_config)
        core_config = {}
    await merge_packages_config(hass, config, core_config.get(CONF_PACKAGES, {}), _pack_error)
    core_config.pop(CONF_PACKAGES, None)
    components = set((key.split(' ')[0] for key in config.keys()))
    for domain in components:
        try:
            integration = await loader.async_get_integration(hass, domain)
        except loader.IntegrationNotFound:
            result.add_error('Integration not found: {}'.format(domain))
            continue
        try:
            component = integration.get_component()
        except ImportError:
            result.add_error('Component not found: {}'.format(domain))
            continue
        if hasattr(component, 'CONFIG_SCHEMA'):
            try:
                config = component.CONFIG_SCHEMA(config)
                result[domain] = config[domain]
            except vol.Invalid as ex:
                _comp_error(ex, domain, config)
                continue
        component_platform_schema = getattr(component, 'PLATFORM_SCHEMA_BASE', getattr(component, 'PLATFORM_SCHEMA', None))
        if component_platform_schema is None:
            continue
        platforms = []
        for p_name, p_config in config_per_platform(config, domain):
            try:
                p_validated = component_platform_schema(p_config)
            except vol.Invalid as ex:
                _comp_error(ex, domain, config)
                continue
            if p_name is None:
                platforms.append(p_validated)
                continue
            try:
                p_integration = await loader.async_get_integration(hass, p_name)
            except loader.IntegrationNotFound:
                result.add_error('Integration {} not found when trying to verify its {} platform.'.format(p_name, domain))
                continue
            try:
                platform = p_integration.get_platform(domain)
