def func(self, url, realm, data=None):
    host, selector = splithost(url)
    newurl = 'https://' + host + selector
    proxy = self.proxies['https']
    urltype, proxyhost = splittype(proxy)
    proxyhost, proxyselector = splithost(proxyhost)
    i = proxyhost.find('@') + 1
    proxyhost = proxyhost[i:]
    user, passwd = self.get_user_passwd(proxyhost, realm, i)
    if not (user or passwd):
        return None
    proxyhost = '%s:%s@%s' % (quote(user, safe=''), quote(passwd, safe=''), proxyhost)
    self.proxies['https'] = 'https://' + proxyhost + proxyselector
    if data is None:
        return self.open(newurl)
    else:
        return self.open(newurl, data)

def func(self):
    self.config.ir.logger.debug('  compute_routes')
    for chain_key, chain in self._chains.items():
        if self._log_debug:
            self.config.ir.logger.debug(f'    consider chain[{repr(chain_key)}]={chain}')
        if not any((isinstance(h, IRHost) for h in chain.hosts.values())):
            self.config.ir.logger.debug('      reject: is non-HTTP')
            continue
        found_acme = False
        for rv in self.config.route_variants:
            if self._log_debug:
                self.config.ir.logger.debug(f'        consider route {v3prettyroute(dict(rv.route))}')
            matching_hosts = chain.matching_hosts(rv.route)
            if self._log_debug:
                self.config.ir.logger.debug(f'          matching_hosts={[h.hostname for h in matching_hosts]}')
            if not matching_hosts:
                if self._log_debug:
                    self.config.ir.logger.debug(f"          reject: no hosts match {sorted(rv.route['_host_constraints'])}")
                continue
            for host in matching_hosts:
                candidates = []
                hostname = host.hostname
                if self._log_debug:
                    self.config.ir.logger.debug(f'          host={hostname}')
                if host.secure_action is not None and self._security_model != 'INSECURE':
                    matcher = 'always' if self._security_model == 'SECURE' else 'xfp-https'
                    candidates.append((host, matcher, 'Route', rv))
                if host.insecure_action is not None and self._security_model != 'SECURE':
                    matcher = 'always' if self._security_model == 'INSECURE' else 'xfp-http'
                    action = host.insecure_action
                    candidates.append((host, matcher, action, rv))
                for host, matcher, action, rv in candidates:
                    route_precedence = rv.route.get('_precedence', None)
                    extra_info = ''
                    if rv.route['match'].get('prefix', None) == '/.well-known/acme-challenge/':
                        extra_info = ' (force Route for ACME challenge)'
                        action = 'Route'
                        found_acme = True
                    elif self.config.ir.edge_stack_allowed and route_precedence == -1000000 and (rv.route['match'].get('safe_regex', {}).get('regex', None) == '^/$'):
                        extra_info = ' (force Route for fallback Mapping)'
                        action = 'Route'
                    if action != 'Reject':
                        if self._log_debug:
                            self.config.ir.logger.debug(f'          route: accept matcher={matcher} action={action} {extra_info}')
                        variant = dict(rv.get_variant(matcher, action.lower()))
                        variant['_host_constraints'] = set([hostname])
                        chain.add_route(hostname, variant)
                    elif self._log_debug:
                        self.config.ir.logger.debug(f'          route: reject matcher={matcher} action={action} {extra_info}')
        if self.config.ir.edge_stack_allowed and (not found_acme):
            self.config.ir.logger.debug('      punching a hole for ACME')
            for hostname in chain.hosts:
                chain.routes[hostname].insert(0, {'_host_constraints': set(), 'match': {'case_sensitive': True, 'prefix': '/.well-known/acme-challenge/'}, 'direct_response': {'status': 404}})
        if self._log_debug:
            for hostname in chain.hosts:
                for route in chain.routes[hostname]:
                    self.config.ir.logger.debug(f'  CHAIN ROUTE: vhost={hostname} {v3prettyroute(route)}')

