def func(self):
    url = self.request.params.get('url', '')
    if not url.lower().startswith('http://'):
        log.error('This service can only request HTTP protocol')
        return HTTPBadGateway()
    if not self._check_ip_for_httpsproxy(url):
        log.error('Try to access an unathorized network')
        log.error(url)
        return HTTPUnauthorized()
    params_dict = {}
    for key in self.request.params.keys():
        if not key == 'url':
            params_dict[key] = self.request.params.get(key)
    params = urllib.parse.urlencode(params_dict)
    separator = '?'
    if '?' in url:
        separator = '&'
    url = url + separator + params
    timeout = 15
    try:
        f = urllib.request.urlopen(url, None, timeout)
        data = f.read()
    except:
        try:
            f = urllib.request.urlopen(url, None, timeout)
            data = f.read()
        except Exception as e:
            log.exception(e)
            log.error(url)
            return HTTPBadGateway()
    headers = {'Content-Type': f.info()['Content-Type']}
    return Response(data, headers=headers)

def func(self, command, sendData):
    backData = []
    backLen = 0
    status = self.MI_ERR
    irqEn = 0
    waitIRq = 0
    lastBits = None
    n = 0
    if command == self.PCD_AUTHENT:
        irqEn = 18
        waitIRq = 16
    if command == self.PCD_TRANSCEIVE:
        irqEn = 119
        waitIRq = 48
    self.Write_MFRC522(self.CommIEnReg, irqEn | 128)
    self.ClearBitMask(self.CommIrqReg, 128)
    self.SetBitMask(self.FIFOLevelReg, 128)
    self.Write_MFRC522(self.CommandReg, self.PCD_IDLE)
    for i in range(len(sendData)):
        self.Write_MFRC522(self.FIFODataReg, sendData[i])
    self.Write_MFRC522(self.CommandReg, command)
    if command == self.PCD_TRANSCEIVE:
        self.SetBitMask(self.BitFramingReg, 128)
    i = 2000
    while True:
        n = self.Read_MFRC522(self.CommIrqReg)
        i -= 1
        if ~(i != 0 and ~(n & 1) and ~(n & waitIRq)):
            break
    self.ClearBitMask(self.BitFramingReg, 128)
    if i != 0:
        if self.Read_MFRC522(self.ErrorReg) & 27 == 0:
            status = self.MI_OK
            if n & irqEn & 1:
                status = self.MI_NOTAGERR
            if command == self.PCD_TRANSCEIVE:
                n = self.Read_MFRC522(self.FIFOLevelReg)
                lastBits = self.Read_MFRC522(self.ControlReg) & 7
                if lastBits != 0:
                    backLen = (n - 1) * 8 + lastBits
                else:
                    backLen = n * 8
                if n == 0:
                    n = 1
                if n > self.MAX_LEN:
                    n = self.MAX_LEN
                for i in range(n):
                    backData.append(self.Read_MFRC522(self.FIFODataReg))
        else:
            status = self.MI_ERR
    return (status, backData, backLen)

