def func(self, connect_timeout, connect_kw):
    try:
        conn = socks.create_connection((self._host, self._port), proxy_type=self._socks_options['socks_version'], proxy_addr=self._socks_options['proxy_host'], proxy_port=self._socks_options['proxy_port'], proxy_username=self._socks_options['username'], proxy_password=self._socks_options['password'], proxy_rdns=self._socks_options['rdns'], timeout=connect_timeout, **connect_kw)
    except SocketTimeout as e:
        raise ConnectTimeoutError(self, 'Connection to %s timed out. (connect timeout=%s)' % (self._host, connect_timeout))
    except socks.ProxyError as e:
        if e.socket_err:
            error = e.socket_err
            if isinstance(error, SocketTimeout):
                raise ConnectTimeoutError(self, 'Connection to %s timed out. (connect timeout=%s)' % (self._host, connect_timeout))
            else:
                raise NewConnectionError(self, 'Failed to establish a new connection: %s' % error)
        else:
            raise NewConnectionError(self, 'Failed to establish a new connection: %s' % e)
    except SocketError as e:
        raise NewConnectionError(self, 'Failed to establish a new connection: %s' % e)
    return conn

