def func(self, name, user, description=None, options=None, is_hidden=False):
    if isinstance(user, str):
        user = self.user(username=user)
    elif isinstance(user, int):
        user = self.user(pk=user)
    elif isinstance(user, User):
        pass
    else:
        raise IllegalArgumentError('the `user` is not of a type `User`, a `username` or a user id')
    data = dict(name=check_text(name, 'name'), description=check_text(description, 'description') or '', options=check_type(options, dict, 'options') or dict(), is_hidden=check_type(is_hidden, bool, 'is_hidden'))
    url = self._build_url('teams')
    response = self._request('POST', url, json=data)
    if response.status_code != requests.codes.created:
        raise APIError('Could not create Team', response=response)
    new_team = Team(json=response.json().get('results')[0], client=self)
    new_team.add_members([user], role=TeamRoles.OWNER)
    team_members = new_team.members()
    members_to_remove = [self.user(username=u.get('username')) for u in team_members if u.get('username') != user.username]
    if members_to_remove:
        new_team.remove_members(members_to_remove)
        new_team.refresh()
    return new_team

