def func(token, serializer_name, max_age=None):
    serializer = get_serializer(serializer_name)
    user, data = (None, None)
    expired, invalid = (False, False)
    try:
        data = serializer.loads(token, max_age=max_age)
    except SignatureExpired:
        d, data = serializer.loads_unsafe(token)
        expired = True
    except BadSignature:
        invalid = True
    if data:
        user = User.query.get(data[0])
    expired = expired and user is not None
    return (expired, invalid, user)

def func(self, campaign_id, lang, dry_run=True):
    folder = path.join(mailjet_templates.PATH, campaign_id)
    template_id = mailjet_templates.MAP[campaign_id].get('i18n', {}).get(lang)
    new_template_id = None
    if not self._all_translations:
        self._all_translations |= translation.get_all_translations()
    missing_translations = set()
    validation_errors = {}
    def _translate(string):
        try:
            translated_string = self._get_available_translation(string, lang)
        except KeyError:
            missing_translations.add(string)
            return string
        try:
            self._space_checker.check_value(translated_string, lang)
        except ValueError as error:
            validation_errors[translated_string] = error
        return translated_string
    data = translate_mailjet_content(folder, _translate)
    if missing_translations or validation_errors:
        exception = _TemplateTranslationError(missing_translations, validation_errors)
        raise exception
    if template_id:
        response = self._http.get(f'https://api.mailjet.com/v3/REST/template/{template_id}/detailcontent', headers={'Content-Type': 'application/json'}, auth=self._auth)
        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError as error:
            logging.error(response.text, exc_info=error)
            raise
        old_data = response.json()['Data'][0]
        if old_data == data:
            logging.info('Data is already up to date for "%s" in "%s".', campaign_id, lang)
            return _TranslationResult(has_been_updated=False)
    else:
        if dry_run:
            logging.info('Template for "%s" in "%s" would be created.', campaign_id, lang)
            return _TranslationResult(new_template_id=1)
        logging.info('Creating template for "%s" in "%s".', campaign_id, lang)
        response = self._post_mailjet('https://api.mailjet.com/v3/REST/template', data={'Name': f'DO NOT EDIT {campaign_id} ({lang})', 'EditMode': 1, 'Locale': _MAILJET_LOCALES[lang]})
        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError as error:
            logging.error(response.text, exc_info=error)
            raise
        template_id = typing.cast(int, response.json()['Data'][0]['ID'])
        new_template_id = template_id
    if dry_run:
        logging.info('Data would be updated for "%s" in "%s".', campaign_id, lang)
    else:
        logging.info('Updating template for "%s" in "%s".', campaign_id, lang)
        response = self._post_mailjet(f'https://api.mailjet.com/v3/REST/template/{template_id}/detailcontent', data=data)
        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError as error:
            logging.error(response.text, exc_info=error)
            raise
    return _TranslationResult(new_template_id=new_template_id)

def func(self, certificate):
    if not self.ev_oids:
        raise ValueError('No EV OIDs supplied for {} store - cannot detect EV certificates'.format(self.name))
    try:
        cert_policies_ext = certificate.extensions.get_extension_for_oid(ExtensionOID.CERTIFICATE_POLICIES)
    except ExtensionNotFound:
        return False
    cert_policies_value = cast(CertificatePolicies, cert_policies_ext.value)
    for policy in cert_policies_value:
        if policy.policy_identifier in self.ev_oids:
            return True
    return False

