def func(self, pagename, addctx, templatename='page.html', outfilename=None, event_arg=None):
    ctx = self.globalcontext.copy()
    ctx['pagename'] = ctx['current_page_name'] = pagename
    ctx['encoding'] = self.config.html_output_encoding
    default_baseuri = self.get_target_uri(pagename)
    default_baseuri = default_baseuri.rsplit('#', 1)[0]
    if self.config.html_baseurl:
        ctx['pageurl'] = posixpath.join(self.config.html_baseurl, pagename + self.out_suffix)
    else:
        ctx['pageurl'] = None
    def pathto(otheruri, resource=False, baseuri=default_baseuri):
        if resource and '://' in otheruri:
            return otheruri
        elif not resource:
            otheruri = self.get_target_uri(otheruri)
        uri = relative_uri(baseuri, otheruri) or '#'
        if uri == '#' and (not self.allow_sharp_as_current_path):
            uri = baseuri
        return uri
    ctx['pathto'] = pathto
    def css_tag(css):
        attrs = []
        for key in sorted(css.attributes):
            value = css.attributes[key]
            if value is not None:
                attrs.append('%s="%s"' % (key, htmlescape(value, True)))
        attrs.append('href="%s"' % pathto(css.filename, resource=True))
        return '<link %s />' % ' '.join(attrs)
    ctx['css_tag'] = css_tag
    def hasdoc(name):
        if name in self.env.all_docs:
            return True
        elif name == 'search' and self.search:
            return True
        elif name == 'genindex' and self.get_builder_config('use_index', 'html'):
            return True
        return False
    ctx['hasdoc'] = hasdoc
    def warn(*args, **kwargs):
        warnings.warn('The template function warn() was deprecated. Use warning() instead.', RemovedInSphinx30Warning, stacklevel=2)
        self.warn(*args, **kwargs)
        return ''
    ctx['warn'] = warn
    ctx['toctree'] = lambda **kw: self._get_local_toctree(pagename, **kw)
    self.add_sidebars(pagename, ctx)
    ctx.update(addctx)
    self.update_page_context(pagename, templatename, ctx, event_arg)
    newtmpl = self.app.emit_firstresult('html-page-context', pagename, templatename, ctx, event_arg)
    if newtmpl:
        templatename = newtmpl
    try:
        output = self.templates.render(templatename, ctx)
    except UnicodeError:
        logger.warning(__('a Unicode error occurred when rendering the page %s. Please make sure all config values that contain non-ASCII content are Unicode strings.'), pagename)
        return
    except Exception as exc:
        raise ThemeError(__('An error happened in rendering the page %s.\nReason: %r') % (pagename, exc))
    if not outfilename:
        outfilename = self.get_outfilename(pagename)
    ensuredir(path.dirname(outfilename))
    try:
        with codecs.open(outfilename, 'w', ctx['encoding'], 'xmlcharrefreplace') as f:
            f.write(output)
    except (IOError, OSError) as err:
        logger.warning(__('error writing file %s: %s'), outfilename, err)
    if self.copysource and ctx.get('sourcename'):
        source_name = path.join(self.outdir, '_sources', os_path(ctx['sourcename']))
        ensuredir(path.dirname(source_name))
        copyfile(self.env.doc2path(pagename), source_name)

def func(cls, name, bases, attrs):
    if name == 'BaseForm':
        return type.__new__(cls, name, bases, attrs)
    form_type = attrs['form_type'].kwargs['default']
    form = type.__new__(cls, name, bases, attrs)
    if form.__dict__.get('get_request_allowed', True):
        vs.rbac['get_requests'][f'/{form_type}_form'] = 'access'
    if hasattr(form, 'form_init'):
        form.form_init()
    cls.register_property_list(form, form_type)
    if not hasattr(form, 'custom_properties'):
        form.custom_properties = {}
    form.custom_properties = {**form.custom_properties, **vs.properties['custom'].get(form_type, {})}
    for property, values in form.custom_properties.items():
        if not values.get('form', True):
            continue
        if property in vs.private_properties_set:
            field = PasswordField
        else:
            field = {'bool': BooleanField, 'dict': DictField, 'integer': IntegerField, 'json': JsonField, 'str': StringField, 'select': SelectField, 'multiselect': SelectMultipleField}[values.get('type', 'str')]
        form_kw = {property: values[property] for property in ('default', 'render_kw', 'dont_duplicate') if property in values}
        form_args = []
        if field in (SelectField, SelectMultipleField):
            form_kw['choices'] = values['choices']
        if values.get('mandatory', False):
            form_args.append([InputRequired()])
        field = field(values['pretty_name'], *form_args, **form_kw)
        setattr(form, property, field)
        attrs[property] = field
    if form_type in vs.rbac['rbac_models']:
        form.rbac_properties = vs.rbac['rbac_models'].get(form_type, {})
        setattr(form, 'owners', MultipleInstanceField('Owners', model='user'))
        field_properties = {'type': 'object-list', 'model': 'user'}
        vs.form_properties[form_type]['owners'] = field_properties
    for property, property_name in form.rbac_properties.items():
        field = MultipleInstanceField(property_name, model='group')
        setattr(form, property, field)
        field_properties = {'type': 'object-list', 'model': 'group'}
        vs.form_properties[form_type][property] = field_properties
    vs.form_class[form_type] = form
    properties = {}
    for field_name, field in attrs.items():
        if not isinstance(field, UnboundField):
            continue
        field_type = field.kwargs.pop('type', None)
        if not field_type:
            field_type = field.field_class.type
        properties[field_name] = {'type': field_type, 'model': field.kwargs.get('model', None), 'constraints': field.kwargs.get('constraints', {}), 'dont_duplicate': field.kwargs.get('dont_duplicate', False)}
        if field.args and isinstance(field.args[0], str):
            vs.property_names[field_name] = field.args[0]
        if issubclass(field.field_class, PasswordField) and field_name not in vs.private_properties_set:
            vs.private_properties_set.add(field_name)
    vs.form_properties[form_type].update(properties)
    for base in form.__bases__:
        if not hasattr(base, 'form_type'):
            continue
        base_form_type = base.form_type.kwargs['default']
        form.custom_properties.update(base.custom_properties)
        if base_form_type == 'service':
            form.service_fields = [property for property in properties if property not in form.custom_properties]
        if getattr(base, 'abstract_service', False):
            form.service_fields.extend(vs.form_properties[base_form_type])
        vs.form_properties[form_type].update(vs.form_properties[base_form_type])
    return form

async def func(self, protocol_factory, conn, extra, sslcontext=None, server=None, ssl_handshake_timeout=constants.SSL_HANDSHAKE_TIMEOUT):
    protocol = None
    transport = None
    try:
        protocol = protocol_factory()
        waiter = self.create_future()
        if sslcontext:
            transport = self._make_ssl_transport(conn, protocol, sslcontext, waiter=waiter, server_side=True, extra=extra, server=server, ssl_handshake_timeout=ssl_handshake_timeout)
        else:
            transport = self._make_socket_transport(conn, protocol, waiter=waiter, extra=extra, server=server)
        try:
            await waiter
        except:
            transport.close()
            raise
    except Exception as exc:
        if self._debug:
            context = {'message': 'Error on transport creation for incoming connection', 'exception': exc}
            if protocol is not None:
                context['protocol'] = protocol
            if transport is not None:
