def func(self, protocol_factory, path, *, ssl=None, sock=None, server_hostname=None):
    assert server_hostname is None or isinstance(server_hostname, str)
    if ssl:
        if server_hostname is None:
            raise ValueError('you have to pass server_hostname when using ssl')
    elif server_hostname is not None:
        raise ValueError('server_hostname is only meaningful with ssl')
    if path is not None:
        if sock is not None:
            raise ValueError('path and sock can not be specified at the same time')
        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM, 0)
        try:
            sock.setblocking(False)
            yield from self.sock_connect(sock, path)
        except:
            sock.close()
            raise
    else:
        if sock is None:
            raise ValueError('no path and sock were specified')
        if sock.family != socket.AF_UNIX or not base_events._is_stream_socket(sock):
            raise ValueError('A UNIX Domain Stream Socket was expected, got {!r}'.format(sock))
        sock.setblocking(False)
    transport, protocol = (yield from self._create_connection_transport(sock, protocol_factory, ssl, server_hostname))
    return (transport, protocol)

def func(self, user, token):
