    except ValueError:
        return False
    try:
        ts = base36_to_int(ts_b36)
    except ValueError:
        return False
    for secret in [self.secret, *self.secret_fallbacks]:
        if constant_time_compare(self._make_token_with_timestamp(user, ts, secret), token):
            break
    else:
        return False
    if self._num_seconds(self._now()) - ts > self.TIMEOUT:
        return False
    return True

