def func(self, coder, unpacksize=None, password=None):
    filter_id = SupportedMethods.get_filter_id(coder)
    if filter_id in [FILTER_X86, FILTER_ARM, FILTER_ARMTHUMB, FILTER_POWERPC, FILTER_SPARC]:
        return algorithm_class_map[filter_id][1](size=unpacksize)
    if SupportedMethods.is_native_coder(coder):
        raise UnsupportedCompressionMethodError(coder, 'Unknown method code:{}'.format(coder['method']))
    if filter_id not in algorithm_class_map:
        raise UnsupportedCompressionMethodError(coder, 'Unknown method filter_id:{}'.format(filter_id))
    if algorithm_class_map[filter_id][1] is None:
        raise UnsupportedCompressionMethodError(coder, 'Decompression is not supported by {}.'.format(SupportedMethods.get_method_name_id(filter_id)))
    if SupportedMethods.is_crypto_id(filter_id):
        return algorithm_class_map[filter_id][1](coder['properties'], password, self.block_size)
    elif SupportedMethods.need_property(filter_id):
        return algorithm_class_map[filter_id][1](coder['properties'], self.block_size)
    else:
        return algorithm_class_map[filter_id][1]()

def func(notice, log):
    zsig, body = parse_zephyr_body(notice.message, notice.format)
    is_personal = False
    is_huddle = False
    if notice.opcode == 'PING':
        return
    zephyr_class = notice.cls.lower()
    if zephyr_class == options.nagios_class:
        with open(options.nagios_path, 'w') as f:
            f.write('0\n')
        return
    if notice.recipient != '':
        is_personal = True
    if is_personal and (not options.forward_personals):
        return
    if zephyr_class not in current_zephyr_subs and (not is_personal):
        logger.debug('Skipping ... %s/%s/%s' % (zephyr_class, notice.instance, is_personal))
        return
    if notice.format.startswith('Zephyr error: See') or notice.format.endswith('@(@color(blue))'):
        logger.debug('Skipping message we got from Zulip!')
        return
    if zephyr_class == 'mail' and notice.instance.lower() == 'inbox' and is_personal and (not options.forward_mail_zephyrs):
        return
    if is_personal:
        if body.startswith('CC:'):
            is_huddle = True
            huddle_recipients = [to_zulip_username(x.strip()) for x in body.split('\n')[0][4:].split()]
            if notice.sender not in huddle_recipients:
                huddle_recipients.append(to_zulip_username(notice.sender))
            body = body.split('\n', 1)[1]
    if options.forward_class_messages and notice.opcode.lower() == 'crypt':
        body = decrypt_zephyr(zephyr_class, notice.instance.lower(), body)
    zeph = {'time': str(notice.time), 'sender': notice.sender, 'zsig': zsig, 'content': body}
    if is_huddle:
        zeph['type'] = 'private'
        zeph['recipient'] = huddle_recipients
    elif is_personal:
        zeph['type'] = 'private'
        zeph['recipient'] = to_zulip_username(notice.recipient)
    else:
        zeph['type'] = 'stream'
        zeph['stream'] = zephyr_class
        if notice.instance.strip() != '':
            zeph['subject'] = notice.instance
        else:
            zeph['subject'] = '(instance "%s")' % (notice.instance,)
    if is_personal:
        if notice.cls.lower() != 'message' and notice.instance.lower != 'personal':
            heading = '[-c %s -i %s]\n' % (notice.cls, notice.instance)
        elif notice.cls.lower() != 'message':
            heading = '[-c %s]\n' % (notice.cls,)
        elif notice.instance.lower() != 'personal':
            heading = '[-i %s]\n' % (notice.instance,)
        else:
            heading = ''
        zeph['content'] = heading + zeph['content']
    zeph = decode_unicode_byte_strings(zeph)
    logger.info('Received a message on %s/%s from %s...' % (zephyr_class, notice.instance, notice.sender))
    if log is not None:
        log.write(json.dumps(zeph) + '\n')
        log.flush()
    if os.fork() == 0:
        global CURRENT_STATE
        CURRENT_STATE = States.ChildSending
        try:
            res = send_zulip(zeph)
            if res.get('result') != 'success':
                logger.error('Error relaying zephyr:\n%s\n%s' % (zeph, res))
        except Exception:
            logger.exception('Error relaying zephyr:')
        finally:
            os._exit(0)

async def func(self, path, access_token, post_args=None, **args):
