    return escape.json_decode(response.body)

def func(message_filename, key_filename):
    key_size, n, d = read_key_file(key_filename)
    with open(message_filename) as fo:
        content = fo.read()
    message_length_str, block_size_str, encrypted_message = content.split('_')
    message_length = int(message_length_str)
    block_size = int(block_size_str)
    if key_size < block_size * 8:
        sys.exit('ERROR: Block size is {} bits and key size is {} bits. The RSA cipher requires the block size to be equal to or greater than the key size. Did you specify the correct key file and encrypted file?'.format(block_size * 8, key_size))
    encrypted_blocks = []
    for block in encrypted_message.split(','):
        encrypted_blocks.append(int(block))
    return decrypt_message(encrypted_blocks, message_length, (n, d), block_size)

