def func(self, endpoint, **kwargs):
    url = 'https://api.clockify.me/api/v1/{}'.format(endpoint)
    kwargs['headers'] = kwargs.get('headers', {'Content-Type': 'application/json'})
    kwargs['headers']['X-Api-Key'] = self.api_key
