def func(setting, preview):
    def decorator(cls):
        def init(self, window):
            super(cls, self).__init__(window, setting, preview)
        def run(self, **kwargs):
            self.choose(**kwargs)
        cls.setting = setting
        cls.__init__ = init
        cls.run = run
        return cls
    return decorator

def func(self, msg, ident=None):
    content = msg.get('content', {})
    if content is None:
        content = self.none
    elif isinstance(content, dict):
        content = self.pack(content)
    elif isinstance(content, bytes):
        pass
    elif isinstance(content, unicode_type):
        content = content.encode('utf8')
    else:
        raise TypeError('Content incorrect type: %s' % type(content))
    real_message = [self.pack(msg['header']), self.pack(msg['parent_header']), self.pack(msg['metadata']), content]
    to_send = []
    if isinstance(ident, list):
        to_send.extend(ident)
    elif ident is not None:
        to_send.append(ident)
    to_send.append(DELIM)
    signature = self.sign(real_message)
    to_send.append(signature)
    to_send.extend(real_message)
    return to_send

