def func(self, w_conn, mask, buf):
    if not len(buf[POS]):
        return
    try:
        data = buf[POS].popleft()
        if data is sentinel:
            self._sel.unregister(w_conn)
            w_conn.close()
            return
        byte = w_conn.send(data)
    except socket.error as e:
        if e.args[0] == errno.EWOULDBLOCK:
            logger.info('EWOULDBLOCK occur in send to tunnel')
            buf[POS].appendleft(data[byte:])

def func(self, signature, param_values, arg_types=None):
    prefix = keccak_256(signature.encode('utf-8')).digest()[:4]
    assert len(prefix) == 4
    if signature.find('(') == -1:
        raise RuntimeError('Invalid function signature. Missing "(" and/or ")"...')
    if signature.find(')') - signature.find('(') == 1:
        return prefix
    if arg_types is None:
        types = signature[signature.find('(') + 1:-1]
    else:
        types = arg_types
    encoded_params = encode_abi(types, param_values)
    return prefix + encoded_params

def func(self, abi, address, account=None):
    address = normalise_address(address)
    if account is not None:
        account = normalise_address(account)
    if isinstance(abi, IOBase):
        abi = json.load(abi)
    elif isinstance(abi, str):
        with open(abi) as jsonfile:
            abi = json.load(jsonfile)
    if isinstance(abi, dict) and 'abi' in abi:
        abi = abi['abi']
    else:
        require(isinstance(abi, list), 'Abi must be list, incorrect format')
    func = dict()
    for method in abi:
        if method['type'] != 'function':
            continue
        handler = self._solproxy_bind(method, address, account)
        if handler is None:
            continue
        sig = '%s(%s)' % (method['name'], ','.join([i['type'] for i in method['inputs']]))
        sig_hash = keccak_256(sig.encode('utf-8')).hexdigest()[:8]
        func[method['name']] = handler
        func[method['name'] + '_' + sig_hash] = handler
    return namedtuple('SolProxy', func.keys())(*func.values())

def func(item, tree):
    item = merkle_hash(item)
    idx = tree[0].index(item)
    path = []
    for level in tree[:-1]:
        if idx % 2 == 0:
            path.append(bit_set(level[idx + 1], 255))
        else:
            path.append(level[idx - 1])
        idx = idx // 2
    return path

def func(paths):
    grouped_scopes = {}
    for path, scope in paths:
        grouped_scopes.setdefault(path, []).append(scope)
    fs_dirs = []
    for path, scopes in grouped_scopes.items():
        if len(scopes) == 1:
            fs_dirs.append((path, scopes[0]))
            continue
        for i, scope in enumerate(scopes):
            fs_dirs.append((path.with_suffix('.d') / f'{i}.{scope.type}', scope))
    return fs_dirs

