async def func(self, h2_conn, initial_h11_request=None):
    while True:
        data = await h2_conn.socket.recv(2 ** 16)
        if not data:
            print('eof')
            break
        events = h2_conn._conn.receive_data(data)
        for event in events:
            if isinstance(event, h2.events.RequestReceived):
                stream = H2Stream(h2_conn, event, (None, None))
                try:
                    handler = self.router.match(stream)
                    status, body = await handler(stream)
                except CuriousError as exc:
                    handler = self.router.match_error(exc)
                    status, body = await handler(exc)
                datatype = 'plain/text'
                h2_conn.send(event.stream_id, str(status), datatype, body.encode('utf-8'))
            elif isinstance(event, h2.events.DataReceived):
                h2_conn._conn.reset_stream(event.stream_id)
            elif isinstance(event, h2.events.WindowUpdated):
                if initial_h11_request is not None:
                    stream = H2Stream(h2_conn, initial_h11_request, (None, None))
                    try:
                        handler = self.router.match(stream)
                        status, body = await handler(stream)
                    except CuriousError as exc:
                        handler = self.router.match_error(exc)
                        status, body = await handler(exc)
                    datatype = 'plain/text'
                    h2_conn.send(event.stream_id + 1, str(status), datatype, body.encode('utf-8'))
                    initial_h11_request = None
        await h2_conn.sendall()

async def func(self, func, src_path, dest_item, dest_provider):
    folder = await dest_provider.create_folder(item=dest_item, new_name=src_path.name)
    folder.children = []
    items = await self.children(item=src_path)
    for i in range(0, len(items), CONCURRENT_OPS):
        futures = []
        for item in items[i:i + CONCURRENT_OPS]:
            futures.append(asyncio.ensure_future(func(dest_provider, item=item, destination_item=folder)))
            if item.is_folder:
                await futures[-1]
        if not futures:
            continue
        done, _ = await asyncio.wait(futures)
        for fut in done:
            folder.children.append(fut.result())
    return folder

def func(self):
    x = 0
    y = 0
    self._draw_pixel(x, y)
    for step in range(self.resolution + 1):
        chance = random()
        if chance > 0.93:
            w_pass = 4
        elif chance > 0.87:
            w_pass = 3
        elif chance > 0.1:
            w_pass = 2
        else:
            w_pass = 1
        a, b, c, d, e, f = self._w_values(w_pass)
        w_x = a * x + b * y
        w_y = c * x + d * y + f
        self._draw_pixel(w_x, w_y)
        x = w_x
        y = w_y
    if self.resolution < 50000:
        self.resolution += 500
    else:
        self.stopped = True

