def func(self, arr, variables, start_idx):
    if not isinstance(arr, KspArray):
        raise TypeError(f'arr has to be instance of {KspArray}')
    self.__vars = list()
    idx = 0
    for var in variables:
        if isinstance(var, (int, str, float)):
            arr[idx + start_idx] <<= var
            self.__vars.append(arr[idx + start_idx])
            idx += 1
            continue
        if not isinstance(var, (KspVar, kLoc)):
            raise TypeError('all variables has to be instance of ' + f'{(KspVar, kLoc, int, str, float)}. ' + f'Type of {var} is {type(var)}')
        if isinstance(var, kLoc):
            if var._size > 1:
                self.__vars.append(StackFrameArray(arr, idx + start_idx, idx + start_idx + var._size))
                with For(var._size) as seq:
                    for val in seq:
                        arr[val + idx + start_idx] <<= arr.default
                    idx += var._size
            else:
                arr[idx + start_idx] <<= arr.default
                self.__vars.append(arr[idx + start_idx])
                idx += 1
            continue
        if isinstance(var, KspArray):
            self.__vars.append(StackFrameArray(arr, idx + start_idx, idx + start_idx + len(var)))
            with For(len(var)) as seq:
                for val in seq:
                    self.__vars[-1][val] = var[val]
                    idx += 1
            continue
        arr[idx + start_idx] <<= var
        self.__vars.append(arr[idx + start_idx])
        idx += 1
    self.__size = idx

def func(self, show_loop_exception_msg=True):
    if self._done:
        raise RuntimeError('cannot run training loop multiple times')
    try:
        os.makedirs(self.out)
    except OSError:
        pass
    extension_order = sorted(self._extensions.keys(), key=lambda name: self._extensions[name].priority, reverse=True)
    extensions = [(name, self._extensions[name]) for name in extension_order]
    self._start_at = _get_time()
    for _, entry in extensions:
        initializer = getattr(entry.extension, 'initialize', None)
        finished = getattr(entry.trigger, 'finished', False)
        if initializer and (not finished):
            initializer(self)
    update = self.updater.update
    reporter = self.reporter
    stop_trigger = self.stop_trigger
    try:
        while not stop_trigger(self):
            self.observation = {}
            with reporter.scope(self.observation):
                update()
                for name, entry in extensions:
                    if entry.trigger(self):
                        entry.extension(self)
    except Exception as e:
        if show_loop_exception_msg:
            f = sys.stderr
            f.write('Exception in main training loop: {}\n'.format(e))
            f.write('Traceback (most recent call last):\n')
            traceback.print_tb(sys.exc_info()[2])
            f.write('Will finalize trainer extensions and updater before reraising the exception.\n')
        exc_info = sys.exc_info()
        for _, entry in extensions:
            handler = getattr(entry.extension, 'on_error', None)
            if handler:
                try:
                    handler(self, e, sys.exc_info()[2])
                except Exception as he:
                    f.write('Exception in error handler: {}\n'.format(he))
                    f.write('Traceback (most recent call last):\n')
                    traceback.print_tb(sys.exc_info()[2])
        six.reraise(*exc_info)
    finally:
        for _, entry in extensions:
            finalize = getattr(entry.extension, 'finalize', None)
            if finalize:
                finalize()
        self.updater.finalize()
    self._final_elapsed_time = self.elapsed_time
    self._done = True

