    yesV, noV = (False, False)
    yesW, noW = (False, False)
    for c in colors:
        playableValue = len(self.bot.game.playedCards[c]) + 1
        for v in self.bot.values:
            if self.cantBe[c][v]:
                continue
            if v < playableValue:
                noP = True
                noV = True
                yesW = True
            elif v == playableValue:
