def func(vocabulary_path):
    with open(vocabulary_path, 'r') as file_handler:
        raw_lines = file_handler.readlines()
    sections = []
    current_section = []
    for line in raw_lines:
        processed_line = line.strip()
        if not processed_line:
            continue
        if processed_line.startswith('#') and current_section:
            sections.append(current_section)
            current_section = []
        current_section.append(processed_line)
    if current_section:
        sections.append(current_section)
    sorted_sections = []
    for section_num, section in enumerate(sections, 1):
        sorted_sections.append([f'{r}\n' for r in section if r.startswith('#')] + sorted((f'{r}\n' for r in section if not r.startswith('#'))) + (['\n'] if section_num < len(sections) else []))
    with open(vocabulary_path, 'w') as file_handler:
        file_handler.writelines(flat(sorted_sections))

def func(cla55):
    if cla55 is None:
        return '?'
    if issubclass(cla55, Initializer) and cla55 != Initializer:
        init_fn = cla55()._init_function
        return f'{init_fn.__module__}.{init_fn.__name__}'
    origin = getattr(cla55, '__origin__', None)
    args = getattr(cla55, '__args__', ())
    if origin == Dict:
        key_type, value_type = args
        return f'Dict[{func(key_type)}, {func(value_type)}]'
    elif origin in (Tuple, List, Sequence):
        return f"{_remove_prefix(str(origin))}[{', '.join((func(arg) for arg in args))}]"
    elif origin == Union:
        if len(args) == 2 and args[-1] == type(None):
            return f'Optional[{func(args[0])}]'
        else:
            return f"Union[{', '.join((func(arg) for arg in args))}]"
    else:
        return _remove_prefix(f'{cla55.__module__}.{cla55.__name__}')

