def func(self, name, packages, config_path=None, venv_path=None):
    if not config_path:
        config_path = self._search_path[-1]
        self.info('Defaulting config_path to %s' % config_path)
    config_file, config_file_path = self._file_path(config_path)
    config = ConfigParser(allow_no_value=True)
    if self.deps.exists(config_file_path):
        with self.deps.read(config_file_path) as in_file:
            config.read_file(in_file)
    if not config.has_section(_s):
        config.add_section(_s)
    requirements = self._packages_section(config, name, _r)
    venv = VEnv(name, self.deps.venv_deps(), config_path, requirements=requirements, prerequisites=self._packages_section(config, name, _p), location=venv_path)
    for p, s in self.deps.scripts(venv, packages):
        self.deps.echo('Registering %s from %s into %s' % (s, p, name))
        config.set(_s, s, name)
    if not config.has_section(name):
        config.add_section(name)
    config.set(name, _r, '\n'.join(sorted(requirements | set(packages))))
    self.deps.write(config, config_file_path)

def func(self, ctx):
    if not isinstance(ctx.obj, VenvConfig):
        raise TypeError('ctx.obj must be a VEnvConfig')
    cmd = ctx.info_name
    if not cmd:
        raise TypeError('ctx.info_name must be given')
    name = cmd.lower()
    args = ctx.args
    if name in ctx.obj.scripts:
        v = ctx.obj.scripts[name]
    elif name in ctx.obj.venvs:
        v = name
        if len(args) == 0:
            echo('Insufficient parameters', err=True)
            return
        cmd = args.pop(0)
    else:
        echo('Unknown script or venv: "%s"' % ctx.info_name, err=True)
        return
    venv = ctx.obj.venvs[v]
    if venv.create():
        venv.install(*venv.requirements)
    else:
        ctx.obj.info('Using venv %s at %s' % (venv.name, venv.env_path))
    result = venv.run(cmd, *args)
    ctx.exit(result)

