def func(self, protocol_factory, host=None, port=None, *, ssl=None, family=0, proto=0, flags=0, sock=None, local_addr=None, server_hostname=None):
    if server_hostname is not None and (not ssl):
        raise ValueError('server_hostname is only meaningful with ssl')
    if server_hostname is None and ssl:
        if not host:
            raise ValueError('You must set server_hostname when using ssl without a host')
        server_hostname = host
    if host is not None or port is not None:
        if sock is not None:
            raise ValueError('host/port and sock can not be specified at the same time')
        f1 = _ensure_resolved((host, port), family=family, type=socket.SOCK_STREAM, proto=proto, flags=flags, loop=self)
        fs = [f1]
        if local_addr is not None:
            f2 = _ensure_resolved(local_addr, family=family, type=socket.SOCK_STREAM, proto=proto, flags=flags, loop=self)
            fs.append(f2)
        else:
            f2 = None
        yield from tasks.wait(fs, loop=self)
        infos = f1.result()
        if not infos:
            raise OSError('getaddrinfo() returned empty list')
        if f2 is not None:
            laddr_infos = f2.result()
            if not laddr_infos:
                raise OSError('getaddrinfo() returned empty list')
        exceptions = []
        for family, type, proto, cname, address in infos:
            try:
                sock = socket.socket(family=family, type=type, proto=proto)
                sock.setblocking(False)
                if f2 is not None:
                    for _, _, _, _, laddr in laddr_infos:
                        try:
                            sock.bind(laddr)
                            break
                        except OSError as exc:
                            exc = OSError(exc.errno, 'error while attempting to bind on address {!r}: {}'.format(laddr, exc.strerror.lower()))
                            exceptions.append(exc)
                    else:
                        sock.close()
                        sock = None
                        continue
                if self._debug:
                    logger.debug('connect %r to %r', sock, address)
                yield from self.sock_connect(sock, address)
            except OSError as exc:
                if sock is not None:
                    sock.close()
                exceptions.append(exc)
            except:
                if sock is not None:
                    sock.close()
                raise
            else:
                break
        else:
            if len(exceptions) == 1:
                raise exceptions[0]
            else:
                model = str(exceptions[0])
                if all((str(exc) == model for exc in exceptions)):
                    raise exceptions[0]
                raise OSError('Multiple exceptions: {}'.format(', '.join((str(exc) for exc in exceptions))))
    else:
        if sock is None:
            raise ValueError('host and port was not specified and no sock specified')
        if not _is_stream_socket(sock):
            raise ValueError('A Stream Socket was expected, got {!r}'.format(sock))
    transport, protocol = (yield from self._create_connection_transport(sock, protocol_factory, ssl, server_hostname))
    if self._debug:
        sock = transport.get_extra_info('socket')
        logger.debug('%r connected to %s:%r: (%r, %r)', sock, host, port, transport, protocol)
    return (transport, protocol)

def func(self, sock, protocol_factory, ssl, server_hostname, server_side=False):
    sock.setblocking(False)
    protocol = protocol_factory()
    waiter = self.create_future()
    if ssl:
        sslcontext = None if isinstance(ssl, bool) else ssl
        transport = self._make_ssl_transport(sock, protocol, sslcontext, waiter, server_side=server_side, server_hostname=server_hostname)
    else:
        transport = self._make_socket_transport(sock, protocol, waiter)
    try:
        yield from waiter
    except:
        transport.close()
        raise
    return (transport, protocol)

def func(self, protocol_factory, host=None, port=None, *, family=socket.AF_UNSPEC, flags=socket.AI_PASSIVE, sock=None, backlog=100, ssl=None, reuse_address=None, reuse_port=None):
    if isinstance(ssl, bool):
        raise TypeError('ssl argument must be an SSLContext or None')
    if host is not None or port is not None:
        if sock is not None:
            raise ValueError('host/port and sock can not be specified at the same time')
        AF_INET6 = getattr(socket, 'AF_INET6', 0)
        if reuse_address is None:
            reuse_address = os.name == 'posix' and sys.platform != 'cygwin'
        sockets = []
        if host == '':
            hosts = [None]
        elif isinstance(host, str) or not isinstance(host, collections.Iterable):
            hosts = [host]
        else:
            hosts = host
        fs = [self._create_server_getaddrinfo(host, port, family=family, flags=flags) for host in hosts]
        infos = (yield from tasks.gather(*fs, loop=self))
        infos = set(itertools.chain.from_iterable(infos))
        completed = False
        try:
            for res in infos:
                af, socktype, proto, canonname, sa = res
                try:
                    sock = socket.socket(af, socktype, proto)
                except socket.error:
                    if self._debug:
                        logger.warning('create_server() failed to create socket.socket(%r, %r, %r)', af, socktype, proto, exc_info=True)
                    continue
                sockets.append(sock)
                if reuse_address:
                    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, True)
                if reuse_port:
                    _set_reuseport(sock)
                if af == AF_INET6 and hasattr(socket, 'IPPROTO_IPV6'):
                    sock.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, True)
                try:
                    sock.bind(sa)
                except OSError as err:
                    raise OSError(err.errno, 'error while attempting to bind on address %r: %s' % (sa, err.strerror.lower()))
            completed = True
        finally:
            if not completed:
                for sock in sockets:
                    sock.close()
    else:
        if sock is None:
            raise ValueError('Neither host/port nor sock were specified')
        if not _is_stream_socket(sock):
            raise ValueError('A Stream Socket was expected, got {!r}'.format(sock))
        sockets = [sock]
    server = Server(self, sockets)
    for sock in sockets:
        sock.listen(backlog)
        sock.setblocking(False)
        self._start_serving(protocol_factory, sock, ssl, server, backlog)
    if self._debug:
        logger.info('%r is serving', server)
    return server

