def func(dictionary, list_path, value):
    def recursion(d, l):
        key = l.pop(0)
        if len(l) > 0:
            return recursion(d[key], l)
        else:
            d[key] = value
    l_aux = deepcopy(list_path)
    d_aux = deepcopy(dictionary)
    recursion(d_aux, l_aux)
    return d_aux

