def func(raw_data, flatten='med'):
    for i, num in enumerate(raw_data[2]):
        if num > 130:
            raw_data[2:7, i] = np.NaN
    for i, num in enumerate(raw_data[4]):
        if num > 80:
            raw_data[4, i] = np.NaN
    for i, num in enumerate(raw_data[1]):
        if num <= 60:
            raw_data[1, i] = np.NaN
    raw_data = raw_data[:, ~np.any(np.isnan(raw_data), axis=0)]
    if len(raw_data) < 5:
        raise ValueError('Not enough data ro process ...')
    CA_list = raw_data[4]
    if len(CA_list) <= 0:
        raise ValueError('No data produced...')
    if flatten == 'high':
        b, a = butter(1, 0.01)
    elif flatten == 'med':
        b, a = butter(1, 0.02)
    elif flatten == 'low':
        b, a = butter(1, 0.05)
    else:
        raise ValueError()
    try:
        CA_medfilt = medfilt(CA_list, kernel_size=11)
        assert len(CA_medfilt) == len(CA_list)
        CA_butterfilt = filtfilt(b, a, CA_medfilt)
        assert len(CA_butterfilt) == len(CA_list)
        CA_smoothed = savitzky_golay(CA_medfilt, window_size=101, order=3)
        assert len(CA_smoothed) == len(CA_list)
    except ValueError:
        print('Not enough data for smoothing. Leave processing for long (e.g. 10+ seconds)')
        raise
    data = np.vstack((raw_data, CA_medfilt, CA_smoothed, CA_butterfilt)).transpose()
    return data

def func(self, c):
    peri = cv2.arcLength(c, True)
    approx = cv2.approxPolyDP(c, 0.04 * peri, True)
    if len(approx) == 3:
        shape = 'triangle'
    elif len(approx) == 4:
        x, y, w, h = cv2.boundingRect(approx)
        ar = w / float(h)
        shape = 'square' if ar >= 0.95 and ar <= 1.05 else 'rectangle'
    elif len(approx) == 5:
        shape = 'pentagon'
    else:
        shape = 'circle'
    return shape

def func(self, interval):
    tmp = cast(List[Clamp], self.filter_types(self.selections, Clamp))
    if len(tmp) > 0:
        clamp = tmp[0]
    else:
        clamp = None
    if interval.mono == 0:
        monos = (1, 1, -1, -1)
    elif interval.mono == 1:
        monos = (1, 1)
    else:
        monos = (-1, -1)
    out = []
    for mi, mono in enumerate(monos):
        order = self.order(desc=False if mono == 1 else True)
        ll, ul = interval.values
        if clamp is not None:
            ll = max(ll, clamp.ll)
            ul = min(ul, clamp.ul)
        pos = self.selections.index(interval)
        i = order[pos]
        vals = []
        for j in order:
            if j is None:
                vals.append(None)
            elif j < i:
                vals.append(ll - 1 - (i - j))
            elif j == i:
                if mi % 2 == 0:
                    vals.append(ll - 1)
                else:
                    vals.append(ul + 1)
            else:
                vals.append(ul + 1 - (i - j))
        vals[pos] = None
        fs = [FittedSelection(sel, val) for sel, val in zip(self.selections, vals)]
        out.append(Blueprint(fs, mono))
    return out

def func(chars):
    bounds = re.sub('[^\\[\\(\\]\\)]', '', chars)
    tmp = re.sub('[\\[\\(\\]\\)]', '', chars).split(',')
    if len(tmp) != 2:
        raise ValueError(f'Invalid specification for interval: {chars}')
    vals = []
    for v in tmp:
        if v == 'inf':
            vals.append(np.inf)
        elif v == '-inf':
            vals.append(-np.inf)
        else:
            vals.append(float(v))
    values = cast(Tuple[float, float], tuple(vals))
    return (values, Selection.bounds_from_string(bounds))

