def func(self, x, b, _ell, _u, c, bnorm):
    N = x.shape[0]
    lambda_lower = 2 * c / (bnorm ** 2 + EPS)
    lambda_upper = np.sign(c) * np.inf
    _lambda = lambda_lower
    k = 0
    while True:
        k += 1
        _c = 0
        norm = 0
        if c > 0:
            for n in range(N):
                lam_step = _lambda * b[n] / 2
                if b[n] > 0:
                    max_step = _u - x[n]
                    delta_step = min(max_step, lam_step)
                    _c += b[n] * delta_step
                    norm += delta_step ** 2
                else:
                    max_step = _ell - x[n]
                    delta_step = max(max_step, lam_step)
                    _c += b[n] * delta_step
                    norm += delta_step ** 2
        else:
            for n in range(N):
                lam_step = _lambda * b[n] / 2
                if b[n] > 0:
                    max_step = _ell - x[n]
                    delta_step = max(max_step, lam_step)
                    _c += b[n] * delta_step
                    norm += delta_step ** 2
                else:
                    max_step = _u - x[n]
                    delta_step = min(max_step, lam_step)
                    _c += b[n] * delta_step
                    norm += delta_step ** 2
        if np.abs(_c) < np.abs(c):
            if np.isinf(lambda_upper):
                _lambda *= 2
            else:
                lambda_lower = _lambda
                _lambda = (lambda_upper - lambda_lower) / 2 + lambda_lower
        else:
            lambda_upper = _lambda
            _lambda = (lambda_upper - lambda_lower) / 2 + lambda_lower
        if 0.999 * np.abs(c) - EPS < np.abs(_c) < 1.001 * np.abs(c) + EPS:
            break
    return np.sqrt(norm)

def func(self, params, x0, x, b, min_, max_, c, r):
    lam, mu = params
    N = x0.shape[0]
    g = 0
    d_g_d_lam = 0
    d_g_d_mu = 0
    if mu > 0:
        for n in range(N):
            dx = x0[n] - x[n]
            bn = b[n]
            t = 1 / (2 * mu + EPS)
            u = -lam * bn * t - dx
            if np.abs(u) - t < 0:
                d = dx
            else:
                d = np.sign(u) * (np.abs(u) - t) + dx
                if d + x[n] < min_:
                    d = min_ - x[n]
                elif d + x[n] > max_:
                    d = max_ - x[n]
                else:
                    prefac = np.sign(d - dx) + 2 * mu * d + lam * bn
                    d_g_d_lam -= prefac * bn * t
                    d_g_d_mu -= prefac * 2 * d * t
            g += np.abs(dx - d) + mu * d ** 2 + lam * bn * d
            d_g_d_lam += bn * d
            d_g_d_mu += d ** 2
    else:
        for n in range(N):
            dx = x0[n] - x[n]
            bn = b[n]
            if np.abs(lam * bn) < 1:
                d = dx
            elif np.sign(lam * bn) < 0:
                d = max_ - x[n]
            else:
                d = min_ - x[n]
            g += np.abs(dx - d) + mu * d ** 2 + lam * bn * d
            d_g_d_lam += bn * d
            d_g_d_mu += d ** 2
    g += -mu * r ** 2 - lam * c
    d_g_d_lam -= c
    d_g_d_mu -= r ** 2
    return (-g, -np.array([d_g_d_lam, d_g_d_mu]))

