    for path in paths:
        if path[0] == 'messages':
            if path[1] == 'stickers_used':
                media_paths.add(path)
            elif path[1] == 'inbox':
                if path[3] in {'audio', 'gifs', 'files', 'photos', 'videos'}:
                    media_paths.add(path)
                elif path[-1].endswith('.json'):
                    message_paths.add(path)
            elif path[1] in {'filtered_threads', 'archived_threads'}:
