        b = Bend(element.name[0:_ZGOUBI_LABEL_LENGTH], XL=element['L'], B1=b1, KPOS=3, W_E=we * _np.sign(element['ANGLE']), W_S=ws * _np.sign(element['ANGLE']), KINEMATICS=kinematics, LENGTH_IS_ARC_LENGTH=options.get('LENGTH_IS_ARC_LENGTH', True))
    elif options.get('command') == Dipole:
        if element.N is not None and (not _np.isnan(element.N)):
            field_index = element.N
        elif element.K1 is not None and (not _np.isnan(element.K1)):
            field_index = -(_np.abs(element.L / element.ANGLE).to('m') ** 2 * getattr(element, 'K1', 0.0 * _ureg.m ** (-2))).magnitude
        else:
            field_index = 0
        b = Dipole(element.name[0:_ZGOUBI_LABEL_LENGTH], RM=_np.abs(element.L / element.ANGLE), AT=_np.abs(element.ANGLE), B0=b1, N=field_index)
    if element['TILT'] != 0:
        b.COLOR = 'goldenrod'
    if element['ANGLE'] < 0:
        return [ChangeRef(element.name + '_CRL', TRANSFORMATIONS=[['XR', -(-tilt + _np.pi * _ureg.radian)]]), b, ChangeRef(element.name + '_CRR', TRANSFORMATIONS=[['XR', -tilt + _np.pi * _ureg.radian]])]
    elif _np.isnan(element['TILT']) or element['TILT'] == 0:
        return [b]
    else:
        return [ChangeRef(element.name + '_CRL', TRANSFORMATIONS=[['XR', tilt]]), b, ChangeRef(element.name + '_CRR', TRANSFORMATIONS=[['XR', -tilt]])]

