def func(frequency_hz, khz_option, returns):
    if frequency_hz >= 0:
        pass
    else:
        raise ValueError
    f1 = frequency_hz
    f2 = f1 * f1
    f3 = f1 * f2
    f4 = f2 * f2
    f5 = f1 * f4
    f6 = f3 * f3
    h1 = -4.7373389813783836e-24 * f6 + 2.0438283336061252e-15 * f4 - 1.363894795463638e-07 * f2 + 1
    h2 = 1.3066122574128241e-19 * f5 - 2.1181508875186556e-11 * f3 + 0.0005559488023498643 * f1
    r_itu = 0.0001246332637532143 * f1 / sqrt(h1 * h1 + h2 * h2)
    if returns == 'db':
        if khz_option == '1khz':
            return 0.0 if r_itu == 0.0 else DB_GAIN_1KHZ + 20.0 * log10(r_itu)
        elif khz_option == '2khz':
            return 0.0 if r_itu == 0.0 else DB_GAIN_2KHZ + 20.0 * log10(r_itu)
        else:
            raise ValueError
    elif returns == 'factor':
        if khz_option == '1khz':
            return FACTOR_GAIN_1KHZ * r_itu
        elif khz_option == '2khz':
            return FACTOR_GAIN_2KHZ * r_itu
        else:
            raise ValueError
    else:
        raise ValueError

def func(self, hash_fn):
    if self.is_dir():
        raise IsADirectoryError
    hasher = hash_fn()
    with self.open('rb') as f:
        buf = f.read(self._READ_SIZE)
        while buf:
            hasher.update(buf)
            buf = f.read(self._READ_SIZE)
    return str(hasher.hexdigest())

def func(text, ac_automation):
    prev_start, prev_end = (-1, -1)
    for end, (_, key) in ac_automation.iter(text):
        start = end + 1 - len(key)
        if prev_start < 0:
            prev_start, prev_end = (start, end)
        elif start <= prev_end + 1:
            prev_end = end
        else:
            yield (prev_start, prev_end + 1)
            prev_start, prev_end = (start, end)
    if prev_start >= 0:
        yield (prev_start, prev_end + 1)

