def func(step_inputs):
    adjacency = {}
    for step_input in step_inputs:
        if 'source' in step_input:
            if isinstance(step_input['source'], list):
                vertices_in = [get_step_id(cast(str, src)) for src in step_input['source']]
            else:
                vertices_in = [get_step_id(cast(str, step_input['source']))]
            vertex_out = get_step_id(cast(str, step_input['id']))
            for vertex_in in vertices_in:
                if vertex_in not in adjacency:
                    adjacency[vertex_in] = [vertex_out]
                elif vertex_out not in adjacency[vertex_in]:
                    adjacency[vertex_in].append(vertex_out)
            if vertex_out not in adjacency:
                adjacency[vertex_out] = []
    return adjacency

def func(rec):
    if 'name' in rec:
        name = rec['name']
        if isinstance(name, str):
            return name
        raise ValidationException(f'Expected name field to be a string, was {name}')
    anon_name = ''
    if rec['type'] in ('enum', saladp + 'enum'):
        for sym in rec['symbols']:
            anon_name += sym
        return 'anon.enum_' + hashlib.sha1(anon_name.encode('UTF-8')).hexdigest()
    if rec['type'] in ('record', saladp + 'record'):
        for field in rec['fields']:
            if isinstance(field, Mapping):
                anon_name += field['name']
            else:
                raise ValidationException(f"Expected entries in 'fields' to also be maps, was {field}.")
        return 'record_' + hashlib.sha1(anon_name.encode('UTF-8')).hexdigest()
    if rec['type'] in ('array', saladp + 'array'):
        return ''
    raise ValidationException("Expected enum or record, was {rec['type'])}")

