def func(self, vector_action=None, memory=None, text_action=None):
    vector_action = {} if vector_action is None else vector_action
    memory = {} if memory is None else memory
    text_action = {} if text_action is None else text_action
    if self._loaded and (not self._global_done) and (self._global_done is not None):
        if isinstance(vector_action, (int, np.int_, float, np.float_, list, np.ndarray)):
            if self._num_external_brains == 1:
                vector_action = {self._external_brain_names[0]: vector_action}
            elif self._num_external_brains > 1:
                raise UnityActionException('You have {0} brains, you need to feed a dictionary of brain names a keys, and vector_actions as values'.format(self._num_brains))
            else:
                raise UnityActionException('There are no external brains in the environment, step cannot take a vector_action input')
        if isinstance(memory, (int, np.int_, float, np.float_, list, np.ndarray)):
            if self._num_external_brains == 1:
                memory = {self._external_brain_names[0]: memory}
            elif self._num_external_brains > 1:
                raise UnityActionException('You have {0} brains, you need to feed a dictionary of brain names as keys and memories as values'.format(self._num_brains))
            else:
                raise UnityActionException('There are no external brains in the environment, step cannot take a memory input')
        if isinstance(text_action, (str, list, np.ndarray)):
            if self._num_external_brains == 1:
                text_action = {self._external_brain_names[0]: text_action}
            elif self._num_external_brains > 1:
                raise UnityActionException('You have {0} brains, you need to feed a dictionary of brain names as keys and text_actions as values'.format(self._num_brains))
            else:
                raise UnityActionException('There are no external brains in the environment, step cannot take a value input')
        for brain_name in list(vector_action.keys()) + list(memory.keys()) + list(text_action.keys()):
            if brain_name not in self._external_brain_names:
                raise UnityActionException('The name {0} does not correspond to an external brain in the environment'.format(brain_name))
        for b in self._external_brain_names:
            n_agent = self._n_agents[b]
            if b not in vector_action:
                if self._brains[b].vector_action_space_type == 'discrete':
                    vector_action[b] = [0.0] * n_agent
                else:
                    vector_action[b] = [0.0] * n_agent * self._brains[b].vector_action_space_size
            else:
                vector_action[b] = self._flatten(vector_action[b])
            if b not in memory:
                memory[b] = []
            elif memory[b] is None:
                memory[b] = []
            else:
                memory[b] = self._flatten(memory[b])
            if b not in text_action:
                text_action[b] = [''] * n_agent
            else:
                if text_action[b] is None:
                    text_action[b] = [''] * n_agent
                if isinstance(text_action[b], str):
                    text_action[b] = [text_action[b]] * n_agent
            if not (len(text_action[b]) == n_agent or len(text_action[b]) == 0):
                raise UnityActionException("There was a mismatch between the provided text_action and environment's expectation: The brain {0} expected {1} text_action but was given {2}".format(b, n_agent, len(text_action[b])))
            if not (self._brains[b].vector_action_space_type == 'discrete' and len(vector_action[b]) == n_agent or (self._brains[b].vector_action_space_type == 'continuous' and len(vector_action[b]) == self._brains[b].vector_action_space_size * n_agent)):
                raise UnityActionException("There was a mismatch between the provided action and environment's expectation: The brain {0} expected {1} {2} action(s), but was provided: {3}".format(b, n_agent if self._brains[b].vector_action_space_type == 'discrete' else str(self._brains[b].vector_action_space_size * n_agent), self._brains[b].vector_action_space_type, str(vector_action[b])))
        outputs = self.communicator.exchange(self._generate_step_input(vector_action, memory, text_action))
        if outputs is None:
            raise KeyboardInterrupt
        rl_output = outputs.rl_output
        s = self._get_state(rl_output)
        self._global_done = s[1]
        for _b in self._external_brain_names:
            self._n_agents[_b] = len(s[0][_b].agents)
        return s[0]
    elif not self._loaded:
        raise UnityEnvironmentException('No Unity environment is loaded.')
    elif self._global_done:
        raise UnityActionException("The episode is completed. Reset the environment with 'reset()'")
    elif self.global_done is None:
        raise UnityActionException("You cannot conduct step without first calling reset. Reset the environment with 'reset()'")

