def func(self, stream, length):
    if not self.packets:
        print('NO')
        return
    if length is None:
        stream.extend(self.packets)
        return
    remaining = length
    while True:
        for packet in self.packets:
            if packet.size > remaining * 2:
                return
            stream.append(packet)
            remaining -= packet.size
