def func(self, obj, legal_reason=None, purpose=None, fields='__ALL__', base_encryption_key=None, anonymization=True):
    if not anonymization and (not self.is_reversible(obj)):
        raise self.IrreversibleAnonymizerException(f'{self.__class__.__name__} for obj "{obj}" is not reversible.')
    if base_encryption_key:
        self._base_encryption_key = base_encryption_key
    parsed_fields = Fields(fields, obj.__class__) if not isinstance(fields, Fields) else fields
    if anonymization:
        raw_local_fields = [i for i in parsed_fields.local_fields if not self.is_field_anonymized(obj, i)]
    else:
        raw_local_fields = [i for i in parsed_fields.local_fields if self.is_field_anonymized(obj, i) and self[i].get_is_reversible(obj)]
    if raw_local_fields:
        update_dict = {name: self.get_value_from_obj(self[name], obj, name, anonymization) for name in raw_local_fields}
        if self.Meta.delete_reversion:
            self.delete_reversion(obj, anonymization)
        elif self.Meta.anonymize_reversion:
            self.anonymize_reversion(obj, raw_local_fields, anonymization)
        self.perform_update(obj, update_dict, legal_reason, anonymization=anonymization)
    self.update_related_fields(parsed_fields, obj, legal_reason, purpose, anonymization)

