def func(self, file_name):
    if not self._codepoints:
        raise RuntimeError('cannot load hangul. chars not initialized, yet!')
    with open(file_name, 'r', encoding='utf-8') as hangul_file:
        re_definition = re.compile('^\\s*[0-9]+\\s*0x([0-9A-Fa-f]{4,6})\\s+.*\\((.+)\\)\\s*$')
        for line in hangul_file:
            line = line.strip()
            match = re_definition.match(line)
            if match is None:
                continue
            codepoint_id = hex2id(match.group(1))
            assert codepoint_id is not None
            if codepoint_id >= len(self._codepoints):
                continue
            name = match.group(2)
            codepoint = self.get_codepoint(codepoint_id)
            assert codepoint is not None
            if codepoint.name() == '<unassigned>':
                codepoint.set_name(name)

def func(func, registry=None):
    if registry is None:
        registry = Registry.default()
    sig = signature(func)
    converters = {name: registry.get(param.annotation) or param.annotation for name, param in sig.parameters.items() if param.annotation is not Parameter.empty}
    @wraps(func)
    def wrapper(*args, **kwargs):
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()
        errors = {}
        for name, converter in converters.items():
            try:
                bound.arguments[name] = converter(bound.arguments[name])
            except ValueError as exc:
                errors[name] = str(exc)
        if errors:
            raise ConversionError(**errors)
        return func(*bound.args, **bound.kwargs)
    return wrapper

