async def func(self, __request, *, read_response_body=True, timeout=None, follow_redirection=False, max_redirects=None, max_body_size=None, raise_error=None):
    if follow_redirection:
        return await self._handle_redirection(__request, read_response_body=read_response_body, timeout=timeout, max_redirects=max_redirects, max_body_size=max_body_size, raise_error=raise_error)
    async with self._lock.read_lock:
        _timeout = timeout if timeout is not None else self._timeout
        _max_body_size = max_body_size if max_body_size is not None else self._max_body_size
        _raise_error = raise_error if raise_error is not None else self._raise_error
        conn = await self._get_conn(__request.conn_id, timeout=_timeout)
        try:
            response = await asyncio.wait_for(conn.send_request(__request, read_response_body=read_response_body, max_body_size=_max_body_size), _timeout)
        except asyncio.TimeoutError as e:
            conn.close()
            await conn.wait_closed()
            raise exceptions.RequestTimeout from e
        except Exception:
            conn.close()
            await conn.wait_closed()
            raise
        if read_response_body:
            await self._put_conn(conn)
        if _raise_error and response.status_code >= 400:
            raise exceptions.HttpError(response)
        return response

