    txn_info = {'gas_payer': self.gas_payer, 'gas_payer_priv': self.gas_payer_priv, 'gas': self.gas, 'hmt_server_addr': self.hmt_server_addr}
    try:
        handle_transaction_with_retry(txn_func, self.retry, *[], **txn_info)
        return self.status() == Status.Complete
    except Exception as e:
        LOG.info(f'{txn_event} failed with main credentials: {self.gas_payer}, {self.gas_payer_priv} due to {e}. Using secondary ones...')
    raffle_txn_res = self._raffle_txn(self.multi_credentials, txn_func, [], txn_event)
    job_completed = raffle_txn_res['txn_succeeded']
    if not job_completed:
        LOG.exception(f'{txn_event} failed with all credentials.')
    return self.status() == Status.Complete

