def func(self, pixels):
    result = []
    begin = int(self.y - self.radius)
    end = int(self.y + self.radius)
    for row in range(begin, end + 1):
        angle = 0
        if row < self.y:
            if row == begin:
                angle = math.pi / 2
            else:
                angle = math.asin((self.y - row) / self.radius)
        if row > self.y:
            if row == end:
                angle = math.pi / 2
            else:
                angle = math.asin((row - self.y) / self.radius)
        cathetus = int(math.cos(angle) * self.radius)
        begin = self.x - cathetus
        end = self.x + cathetus
        for col in range(begin, end + 1):
            result.append(pixels[row * self.img_width + col])
    return result

def func(*args, sep=b'', pad=False):
    byte_args = []
    for arg in args:
        if isinstance(arg, int):
            arg = to_bytes(arg, False)
        elif isinstance(arg, str):
            arg = arg.encode('utf-8')
        if pad:
            arg = b'\x00' * (PAD_L - len(arg)) + arg
        byte_args.append(arg)
    return int(sha512(sep.join(byte_args)).hexdigest(), 16)

