def func(self, filename, section_prefix=''):
    self.attempted_config_files.append(filename)
    cp = HandyConfigParser(section_prefix)
    try:
        files_read = cp.read(filename)
    except configparser.Error as err:
        raise CoverageException("Couldn't read config file %s: %s" % (filename, err))
    if not files_read:
        return False
    self.config_files.extend(files_read)
    try:
        for option_spec in self.CONFIG_FILE_OPTIONS:
            self._set_attr_from_config_option(cp, *option_spec)
    except ValueError as err:
        raise CoverageException("Couldn't read config file %s: %s" % (filename, err))
    all_options = collections.defaultdict(set)
    for option_spec in self.CONFIG_FILE_OPTIONS:
        section, option = option_spec[1].split(':')
        all_options[section].add(option)
    for section, options in iitems(all_options):
        if cp.has_section(section):
            for unknown in set(cp.options(section)) - options:
                if section_prefix:
                    section = section_prefix + section
                raise CoverageException("Unrecognized option '[%s] %s=' in config file %s" % (section, unknown, filename))
    if cp.has_section('paths'):
        for option in cp.options('paths'):
            self.paths[option] = cp.getlist('paths', option)
    for plugin in self.plugins:
        if cp.has_section(plugin):
            self.plugin_options[plugin] = cp.get_section(plugin)
    return True

def func(self, code, options, format, prefix='graphviz'):
    graphviz_dot = options.get('graphviz_dot', self.builder.config.graphviz_dot)
    hashkey = (code + str(options) + str(graphviz_dot) + str(self.builder.config.graphviz_dot_args)).encode('utf-8')
    fname = '%s-%s.%s' % (prefix, sha1(hashkey).hexdigest(), format)
    relfn = posixpath.join(self.builder.imgpath, fname)
    outfn = path.join(self.builder.outdir, self.builder.imagedir, fname)
    if path.isfile(outfn):
        return (relfn, outfn)
    if hasattr(self.builder, '_graphviz_warned_dot') and self.builder._graphviz_warned_dot.get(graphviz_dot):
        return (None, None)
    ensuredir(path.dirname(outfn))
    if isinstance(code, text_type):
        code = code.encode('utf-8')
    dot_args = [graphviz_dot]
    dot_args.extend(self.builder.config.graphviz_dot_args)
    dot_args.extend(['-T' + format, '-o' + outfn])
    docname = options.get('docname', 'index')
    cwd = path.dirname(path.join(self.builder.srcdir, docname))
    if format == 'png':
        dot_args.extend(['-Tcmapx', '-o%s.map' % outfn])
    try:
        p = Popen(dot_args, stdout=PIPE, stdin=PIPE, stderr=PIPE, cwd=cwd)
    except OSError as err:
        if err.errno != ENOENT:
            raise
        logger.warning(__('dot command %r cannot be run (needed for graphviz output), check the graphviz_dot setting'), graphviz_dot)
        if not hasattr(self.builder, '_graphviz_warned_dot'):
            self.builder._graphviz_warned_dot = {}
        self.builder._graphviz_warned_dot[graphviz_dot] = True
        return (None, None)
    try:
        stdout, stderr = p.communicate(code)
    except (OSError, IOError) as err:
        if err.errno not in (EPIPE, EINVAL):
            raise
        stdout, stderr = (p.stdout.read(), p.stderr.read())
        p.wait()
    if p.returncode != 0:
        raise GraphvizError(__('dot exited with error:\n[stderr]\n%s\n[stdout]\n%s') % (stderr, stdout))
    if not path.isfile(outfn):
        raise GraphvizError(__('dot did not produce an output file:\n[stderr]\n%s\n[stdout]\n%s') % (stderr, stdout))
    return (relfn, outfn)

def func(self, math):
    image_format = self.builder.config.imgmath_image_format.lower()
