def func(self, mod_seq):
    updates_ret = set()
    expunges_ret = set()
    updates = self._updates
    expunges = self._expunges
    mod_seqs_order = self._mod_seqs_order
    mod_seqs_len = len(mod_seqs_order)
    idx = bisect_left(mod_seqs_order, mod_seq, 0, mod_seqs_len)
    for newer_mod_seq in islice(mod_seqs_order, idx, mod_seqs_len):
        updates_set = updates.get(newer_mod_seq)
        expunges_set = expunges.get(newer_mod_seq)
        if updates_set is not None:
            updates_ret.update(updates_set)
        if expunges_set is not None:
            expunges_ret.update(expunges_set)
    return (frozenset(updates_ret), frozenset(expunges_ret))

async def func(self, state):
    bad_commands = 0
    try:
        greeting = await self._exec(state.do_greeting())
    except ResponseError as exc:
        resp = exc.get_response(b'*')
        resp.condition = ResponseBye.condition
        await self.write_response(resp)
        return
    else:
        await self.write_response(greeting)
    while True:
        try:
            cmd = await self.read_command(state)
        except (ConnectionError, EOFError):
            break
        except CancelledError:
            await self.send_error_disconnect()
            break
        except Exception:
            await self.send_error_disconnect()
            raise
        else:
            prev_cmd = current_command.set(cmd)
            try:
                if isinstance(cmd, AuthenticateCommand):
                    creds = await self.authenticate(state, cmd.mech_name)
                    response = await self._exec(state.do_authenticate(cmd, creds))
                elif isinstance(cmd, IdleCommand):
                    response = await self.idle(state, cmd)
                else:
                    response = await self._exec(state.do_command(cmd))
            except ResponseError as exc:
                resp = exc.get_response(cmd.tag)
                await self.write_response(resp)
                if resp.is_terminal:
                    break
            except AuthenticationError as exc:
                msg = bytes(str(exc), 'utf-8', 'surrogateescape')
                resp = ResponseBad(cmd.tag, msg)
                await self.write_response(resp)
            except TimeoutError:
                resp = ResponseNo(cmd.tag, b'Operation timed out.', ResponseCode.of(b'TIMEOUT'))
                await self.write_response(resp)
            except (CancelledError, ConnectionError, EOFError):
                await self.send_error_disconnect()
                break
            except Exception:
                await self.send_error_disconnect()
                raise
            else:
                await self.write_response(response)
                if response.is_bad:
                    bad_commands += 1
                    if self.bad_command_limit and bad_commands >= self.bad_command_limit:
                        msg = b'Too many errors, disconnecting.'
                        response.add_untagged(ResponseBye(msg))
                else:
                    bad_commands = 0
                if response.is_terminal:
                    break
                if isinstance(cmd, StartTLSCommand) and isinstance(response, ResponseOk):
                    try:
                        await self.start_tls()
                    except ConnectionError:
                        break
                    except SSLError as exc:
                        self._print('%s <->| <TLS failure: %s>', exc.reason)
                        return
            finally:
                await state.do_cleanup()
                current_command.reset(prev_cmd)

