def func(auth_lines, passwords, keycert_obj_pk=None):
    hashers = get_password_hashers(permit_legacy=True)
    for auth in auth_lines:
        if keycert_obj_pk and auth.upper() == keycert_obj_pk.upper():
            return keycert_obj_pk.upper()
        if ' ' not in auth:
            continue
        scheme, hash = auth.split(' ', 1)
        scheme = scheme.upper()
        hasher = hashers.get(scheme)
        if hasher:
            for password in passwords:
                try:
                    if hasher.verify(password, hash):
                        return scheme
                except ValueError:
                    pass
    return None

def func(self, password, file_path=None, gpg_path=None):
    changes_command = shlex.split('git secret changes')
    if gpg_path:
        changes_command.extend(['-d', gpg_path])
    changes_command.extend(['-p', password])
    if file_path:
        changes_command.append(file_path)
    output = subprocess.run(args=changes_command, capture_output=True, cwd=self.repo_path)
    if output.returncode != 0:
        raise GitSecretException('Error running git secret command.  stdout: %s; stderr: %s' % (output.stdout.decode('utf-8'), output.stderr.decode('utf-8')))
    return str(output.stdout.decode('utf-8'))

def func(center_door, position, obstacles, detection_range):
    not_detected = -1
    n = len(position)
    distance = np.full(shape=n, fill_value=detection_range, dtype=np.float64)
    detected_exit = np.full(shape=n, fill_value=not_detected, dtype=np.int64)
    has_detected = np.zeros(shape=n, dtype=np.bool_)
    for i in range(n):
        for c in range(len(center_door)):
            if is_obstacle_between_points(position[i], center_door[c], obstacles):
                continue
            d = length(center_door[c] - position[i])
            if d < distance[i]:
                distance[i] = d
                detected_exit[i] = c
                has_detected[i] = True
    return (detected_exit, has_detected)

