def func(self, x, b, _ell, _u, c, bnorm):
    N = x.shape[0]
    lambda_lower = 2 * c / bnorm ** 2
    lambda_upper = np.sign(c) * np.inf
    _lambda = lambda_lower
    k = 0
    while True:
        k += 1
        _c = 0
        norm = 0
        if c > 0:
            for n in range(N):
                lam_step = _lambda * b[n] / 2
                if b[n] > 0:
                    max_step = _u - x[n]
                    delta_step = min(max_step, lam_step)
                    _c += b[n] * delta_step
                    norm += delta_step ** 2
                else:
                    max_step = _ell - x[n]
                    delta_step = max(max_step, lam_step)
                    _c += b[n] * delta_step
                    norm += delta_step ** 2
        else:
            for n in range(N):
                lam_step = _lambda * b[n] / 2
                if b[n] > 0:
                    max_step = _ell - x[n]
                    delta_step = max(max_step, lam_step)
                    _c += b[n] * delta_step
                    norm += delta_step ** 2
                else:
                    max_step = _u - x[n]
                    delta_step = min(max_step, lam_step)
                    _c += b[n] * delta_step
                    norm += delta_step ** 2
        if np.abs(_c) < np.abs(c):
            if np.isinf(lambda_upper):
                _lambda *= 2
            else:
                lambda_lower = _lambda
                _lambda = (lambda_upper - lambda_lower) / 2 + lambda_lower
        else:
            lambda_upper = _lambda
            _lambda = (lambda_upper - lambda_lower) / 2 + lambda_lower
        if 0.999 * np.abs(c) - EPS < np.abs(_c) < 1.001 * np.abs(c) + EPS:
            break
    return np.sqrt(norm)

def func(self, params, x0, x, b, min_, max_, c, r):
    N = x0.shape[0]
    s = -np.sign(c)
    _mu = params[0]
    t = 1 / (2 * _mu + EPS)
    g = -_mu * r ** 2
    grad_mu = -r ** 2
    for n in range(N):
        d = -s * b[n] * t
        if d < min_ - x[n]:
            d = min_ - x[n]
        elif d > max_ - x[n]:
            d = max_ - x[n]
        else:
            grad_mu += (b[n] + 2 * _mu * d) * (b[n] / (2 * _mu ** 2 + EPS))
        grad_mu += d ** 2
        g += (b[n] + _mu * d) * d
    return (-g, -np.array([grad_mu]))

def func(self, lam, mu, x0, x, b, min_, max_, c, r, touchup=True):
    delta = np.empty_like(x0)
    N = x0.shape[0]
    b_dot_d = 0
    norm_d = 0
    distance = 0
    if mu > 0:
        for n in range(N):
            dx = x0[n] - x[n]
            bn = b[n]
            t = 1 / (2 * mu)
            u = -lam * bn * t - dx
            if np.abs(u) - t < 0:
                d = dx
            else:
                d = np.sign(u) * (np.abs(u) - t) + dx
                if d + x[n] < min_:
                    d = min_ - x[n]
                elif d + x[n] > max_:
                    d = max_ - x[n]
            delta[n] = d
            b_dot_d += b[n] * d
            norm_d += d ** 2
            distance += np.abs(d - dx)
    else:
        for n in range(N):
            dx = x0[n] - x[n]
            bn = b[n]
            if np.abs(lam * bn) < 1:
                d = dx
            elif np.sign(lam * bn) < 0:
                d = max_ - x[n]
            else:
                d = min_ - x[n]
            delta[n] = d
            b_dot_d += b[n] * d
            norm_d += d ** 2
            distance += np.abs(d - dx)
    if touchup:
        dc = c - b_dot_d
        k = 0
        min_distance = np.inf
        min_distance_idx = 0
        for n in range(N):
            if np.abs(b[n]) > 0:
                dx = x0[n] - x[n]
                old_d = delta[n]
                new_d = old_d + dc / b[n]
                if x[n] + new_d <= max_ and x[n] + new_d >= min_ and (norm_d - old_d ** 2 + new_d ** 2 <= r ** 2):
                    if k == 0:
                        min_distance = distance - np.abs(old_d - dx) + np.abs(new_d - dx)
                        min_distance_idx = n
                        k += 1
                    else:
                        new_distance = distance - np.abs(old_d - dx) + np.abs(new_d - dx)
                        if min_distance > new_distance:
                            min_distance = new_distance
                            min_distance_idx = n
        if k > 0:
            idx = min_distance_idx
            old_d = delta[idx]
            new_d = old_d + dc / b[idx]
            delta[idx] = new_d
    return delta

async def func(ctx, nxt):
    LEMON_CORS_ORIGIN_WHITELIST = settings.LEMON_CORS_ORIGIN_WHITELIST
    LEMON_CORS_ORIGIN_REGEX_WHITELIST = settings.LEMON_CORS_ORIGIN_REGEX_WHITELIST
    LEMON_CORS_ORIGIN_ALLOW_ALL = settings.LEMON_CORS_ORIGIN_ALLOW_ALL
    LEMON_CORS_ALLOW_METHODS = settings.LEMON_CORS_ALLOW_METHODS
    LEMON_CORS_ALLOW_HEADERS = settings.LEMON_CORS_ALLOW_HEADERS
    LEMON_CORS_EXPOSE_HEADERS = settings.LEMON_CORS_EXPOSE_HEADERS
    LEMON_CORS_ALLOW_CREDENTIALS = settings.LEMON_CORS_ALLOW_CREDENTIALS
    LEMON_CORS_MAX_AGE = settings.LEMON_CORS_MAX_AGE
    if ctx.req is None:
        return
    headers = ctx.req.headers
    origin = headers.get('origin', None)
    origin_header = origin
    if origin is None:
        return await nxt()
    if LEMON_CORS_ORIGIN_ALLOW_ALL:
        origin_header = '*'
    if ctx.req.method == 'OPTIONS':
        acrm = headers.get('access-control-request-method', None)
        acrh = headers.get('access-control-request-headers', None)
        if acrm is None:
            return await nxt()
        matched = False
        if LEMON_CORS_ORIGIN_ALLOW_ALL:
            matched = True
        else:
            for domain in LEMON_CORS_ORIGIN_WHITELIST:
                if domain == origin:
                    matched = True
            for domain_pattern in LEMON_CORS_ORIGIN_REGEX_WHITELIST:
                if re.match(domain_pattern, origin):
                    matched = True
        if matched is False:
            ctx.status = 200
            return
        ctx.res.headers['access-control-allow-origin'] = origin_header
        if LEMON_CORS_ALLOW_CREDENTIALS:
            ctx.res.headers['access-control-allow-credentials'] = 'true'
        ctx.res.headers['access-control-max-age'] = LEMON_CORS_MAX_AGE
        ctx.res.headers['access-control-allow-methods'] = ','.join(LEMON_CORS_ALLOW_METHODS)
        ctx.res.headers['access-control-allow-headers'] = ','.join(LEMON_CORS_ALLOW_HEADERS) or acrh
        ctx.status = 204
        return
    ctx.res.headers['access-control-allow-origin'] = origin_header
    if LEMON_CORS_ALLOW_CREDENTIALS:
        ctx.res.headers['access-control-allow-credentials'] = 'true'
    if LEMON_CORS_EXPOSE_HEADERS:
        ctx.res.headers['access-control-expose-headers'] = ','.join(LEMON_CORS_EXPOSE_HEADERS)
    return await nxt()

