def func(ray_near, ray_dir, V):
    v1 = V[0]
    v2 = V[1]
    v3 = V[2]
    eps = 1e-06
    edge1 = v2 - v1
    edge2 = v3 - v1
    pvec = np.cross(ray_dir, edge2)
    det = edge1.dot(pvec)
    if abs(det) < eps:
        return (False, None)
    inv_det = 1.0 / det
    tvec = ray_near - v1
    u = tvec.dot(pvec) * inv_det
    if u < 0.0 or u > 1.0:
        return (False, None)
    qvec = np.cross(tvec, edge1)
    v = ray_dir.dot(qvec) * inv_det
    if v < 0.0 or u + v > 1.0:
        return (False, None)
    t = edge2.dot(qvec) * inv_det
    if t < eps:
        return (False, None)
    return (True, t)

