def func(self, wikitext, category_info):
    wikicode = mwparserfromhell.parse(wikitext)
    for index, wikilink in enumerate(wikicode.nodes):
        if not isinstance(wikilink, Wikilink):
            continue
        if not self._is_category(wikilink, category_info):
            continue
        if self._reject_category_link(wikilink, category_info):
            if index - 1 >= 0 and isinstance(wikicode.nodes[index - 1], mwparserfromhell.nodes.text.Text) and wikicode.nodes[index - 1].value.endswith('\n'):
                wikicode.nodes[index - 1].value = wikicode.nodes[index - 1].value[:-1]
            elif index + 1 < len(wikicode.nodes) and isinstance(wikicode.nodes[index + 1], mwparserfromhell.nodes.text.Text) and wikicode.nodes[index + 1].value.startswith('\n'):
                wikicode.nodes[index + 1].value = wikicode.nodes[index + 1].value[1:]
            del wikicode.nodes[index]
            break
    return str(wikicode)

