def func(parser, dependency, matching_rules):
    used_rules = OrderedSet()
    for import_module in dependency.sub_imports:
        used_rule = None
        for matching_rule in matching_rules:
            if re.match(f'{parser.wildcard_to_regex(matching_rule.specific_rule_wildcard)}$', f'{dependency.main_import}.{import_module}'):
                used_rule = matching_rule
                used_rules.add(used_rule)
        if not used_rule:
            raise NotAllowedDependencyException(Module(f'{dependency.main_import}.{import_module}'), [r.specific_rule_wildcard for r in matching_rules])
    return used_rules

