def func(node):
    if not node.args.kwonlyargs:
        return node
    if node.args.kwarg:
        kw_name = node.args.kwarg.arg
    else:
        kw_name = 'kwargs'
        node.args.kwarg = ast.arg(arg=kw_name, annotation=None)
    kwonlyargs = reversed(node.args.kwonlyargs)
    kw_defaults = reversed(node.args.kw_defaults)
    for arg, default in zip(kwonlyargs, kw_defaults):
        arg_name = arg.arg
        if default is None:
            node_value = ast.Subscript(value=ast.Name(id=kw_name, ctx=ast.Load()), slice=ast.Index(value=AstStr(s=arg_name)), ctx=ast.Load())
        elif not isinstance(default, common.ConstantNodeTypes):
            msg = f'Keyword only arguments must be immutable. Found: {default} for {arg_name}'
            raise common.FixerError(msg, node)
        else:
            node_value = ast.Call(func=ast.Attribute(value=ast.Name(id=kw_name, ctx=ast.Load()), attr='get', ctx=ast.Load()), args=[AstStr(s=arg_name), default], keywords=[])
        new_node = ast.Assign(targets=[ast.Name(id=arg_name, ctx=ast.Store())], value=node_value)
        node.body.insert(0, new_node)
    node.args.kwonlyargs = []
    return node

def func(cls, environ):
    typename = cls.__name__
    init_kwargs = {}
    for field in cls._iter_fields():
        if field.env_key in environ:
            try:
                raw_env_val = environ[field.env_key]
                init_kwargs[field.fname] = _parse_val(raw_env_val, field.ftyp)
            except ValueError as err:
                raise ValueError(f"Invalid value '{raw_env_val}' for {field.env_key}. Attepmted to parse '{typename}.{field.fname}' with '{field.ftyp}'.", err)
        elif field.fallback != __fallback_sentinel__:
            init_kwargs[field.fname] = field.fallback
        else:
            raise KeyError(f'No environment variable {field.env_key} ' + f'found for field {typename}.{field.fname}')
    return init_kwargs

