def func(self, *nodes, depth=1, context=0):
    nodes = set(nodes)
    for i in range(depth):
        for n in list(nodes):
            nodes.update(n.inputs)
    if context != 0:
        for n in nodes:
            if n.graph is not None:
                mng = n.graph.manager
        for i in range(context):
            for n in list(nodes):
                nodes.update((n2 for n2, _ in mng.uses[n]))
    self.nodes = nodes

def func(password, cycles, salt, digest):
    assert cycles <= 63
    if cycles == 63:
        ba = bytearray(salt + password + bytes(32))
        key = bytes(ba[:32])
    else:
        rounds = 1 << cycles
        m = _get_hash(digest)
        for round in range(rounds):
            m.update(salt + password + round.to_bytes(8, byteorder='little', signed=False))
        key = m.digest()[:32]
    return key

