                            continue
                        instaloader.context.log('Downloading {} ({})'.format(structure, target))
                        instaloader.download_post(structure, os.path.dirname(target))
                    elif isinstance(structure, StoryItem):
                        if storyitem_filter is not None and (not storyitem_filter(structure)):
                            instaloader.context.log('<{} ({}) skipped>'.format(structure, target), flush=True)
                            continue
                        instaloader.context.log('Attempting to download {} ({})'.format(structure, target))
                        instaloader.download_storyitem(structure, os.path.dirname(target))
                    elif isinstance(structure, Profile):
                        raise InvalidArgumentException('Profile JSON are ignored. Pass "{}" to download that profile'.format(structure.username))
                    else:
                        raise InvalidArgumentException('{} JSON file not supported as target'.format(structure.__class__.__name__))
                continue
            target = target.rstrip('/')
            with instaloader.context.error_catcher(target):
                if target[0] == '@':
                    instaloader.context.log('Retrieving followees of %s...' % target[1:])
                    profile = Profile.from_username(instaloader.context, target[1:])
                    for followee in profile.get_followees():
                        instaloader.save_profile_id(followee)
                        profiles.add(followee)
                elif target[0] == '#':
                    instaloader.download_hashtag(hashtag=target[1:], max_count=max_count, fast_update=fast_update, post_filter=post_filter)
                elif target[0] == '-':
                    instaloader.download_post(Post.from_shortcode(instaloader.context, target[1:]), target)
                elif target[0] == '%':
                    instaloader.download_location(location=target[1:], max_count=max_count, fast_update=fast_update, post_filter=post_filter)
                elif target == ':feed':
                    instaloader.download_feed_posts(fast_update=fast_update, max_count=max_count, post_filter=post_filter)
                elif target == ':stories':
                    instaloader.download_stories(fast_update=fast_update, storyitem_filter=storyitem_filter)
                elif target == ':saved':
                    instaloader.download_saved_posts(fast_update=fast_update, max_count=max_count, post_filter=post_filter)
                else:
                    try:
                        profile = instaloader.check_profile_id(target)
                        if instaloader.context.is_logged_in and profile.has_blocked_viewer:
                            if download_profile_pic or ((download_posts or download_tagged) and (not profile.is_private)):
                                raise ProfileNotExistsException('{} blocked you; But we download her anonymously.'.format(target))
                            else:
                                instaloader.context.error('{} blocked you.'.format(target))
                        else:
                            profiles.add(profile)
                    except ProfileNotExistsException as err:
                        if instaloader.context.is_logged_in and (download_profile_pic or download_posts or download_tagged):
                            instaloader.context.log(err)
                            instaloader.context.log('Trying again anonymously, helps in case you are just blocked.')
                            with instaloader.anonymous_copy() as anonymous_loader:
                                with instaloader.context.error_catcher():
                                    anonymous_retry_profiles.add(anonymous_loader.check_profile_id(target))
                                    instaloader.context.error('Warning: {} will be downloaded anonymously ("{}").'.format(target, err))
                        else:
                            raise
        if len(profiles) > 1:
            instaloader.context.log('Downloading {} profiles: {}'.format(len(profiles), ' '.join([p.username for p in profiles])))
        if profiles and download_profile_pic and (not instaloader.context.is_logged_in):
            instaloader.context.error('Warning: Use --login to download HD version of profile pictures.')
        instaloader.download_profiles(profiles, download_profile_pic, download_posts, download_tagged, download_highlights, download_stories, fast_update, post_filter, storyitem_filter)
        if anonymous_retry_profiles:
            instaloader.context.log('Downloading anonymously: {}'.format(' '.join([p.username for p in anonymous_retry_profiles])))
            with instaloader.anonymous_copy() as anonymous_loader:
                anonymous_loader.download_profiles(anonymous_retry_profiles, download_profile_pic, download_posts, download_tagged, fast_update=fast_update, post_filter=post_filter)
    except KeyboardInterrupt:
        print('\nInterrupted by user.', file=sys.stderr)
    if instaloader.context.is_logged_in:
        instaloader.save_session_to_file(sessionfile)
    if not targetlist:
        if instaloader.context.is_logged_in:
            instaloader.context.log('No targets were specified, thus nothing has been downloaded.')
        else:
            instaloader.context.log('usage:' + usage_string())

def func(self, profile_name, profile_pic=True, profile_pic_only=False, fast_update=False, download_stories=False, download_stories_only=False, download_tagged=False, download_tagged_only=False, post_filter=None, storyitem_filter=None):
    if isinstance(profile_name, str):
        profile = self.check_profile_id(profile_name.lower())
    else:
        profile = profile_name
    profile_name = profile.username
    if self.save_metadata is not False:
        json_filename = '{0}/{1}_{2}'.format(self.dirname_pattern.format(profile=profile_name, target=profile_name), profile_name, profile.userid)
        self.save_metadata_json(json_filename, profile)
    if self.context.is_logged_in and profile.has_blocked_viewer and (not profile.is_private):
        raise ProfileNotExistsException('Profile {} has blocked you'.format(profile_name))
    if profile_pic or profile_pic_only:
        with self.context.error_catcher('Download profile picture of {}'.format(profile_name)):
            self.download_profilepic(profile)
    if profile_pic_only:
        return
    if profile.is_private:
        if not self.context.is_logged_in:
            raise LoginRequiredException('profile %s requires login' % profile_name)
        if not profile.followed_by_viewer and self.context.username != profile.username:
            raise PrivateProfileNotFollowedException('Profile %s: private but not followed.' % profile_name)
    elif self.context.is_logged_in and (not (download_stories or download_stories_only)):
        self.context.log('profile %s could also be downloaded anonymously.' % profile_name)
    if download_stories or download_stories_only:
        if profile.has_viewable_story:
            with self.context.error_catcher('Download stories of {}'.format(profile_name)):
                self.download_stories(userids=[profile.userid], filename_target=profile_name, fast_update=fast_update, storyitem_filter=storyitem_filter)
        else:
            self.context.log('{} does not have any stories.'.format(profile_name))
    if download_stories_only:
        return
    if download_tagged or download_tagged_only:
        with self.context.error_catcher('Download tagged of {}'.format(profile_name)):
            self.download_tagged(profile, fast_update=fast_update, post_filter=post_filter)
    if download_tagged_only:
        return
    self.context.log('Retrieving posts from profile {}.'.format(profile_name))
    totalcount = profile.mediacount
    count = 1
    for post in profile.get_posts():
        self.context.log('[%3i/%3i] ' % (count, totalcount), end='', flush=True)
        count += 1
        if post_filter is not None and (not post_filter(post)):
            self.context.log('<skipped>')
            continue
        with self.context.error_catcher('Download profile {}'.format(profile_name)):
            downloaded = self.download_post(post, target=profile_name)
            if fast_update and (not downloaded):
                break

