async def func(server_url, auth, resource):
    source = resource['source']
    client = KintoClient(server_url=server_url, auth=auth)
    collection = await client.get_collection(bucket=source['bucket'], id=source['collection'])
    source_metadata = collection['data']
    try:
        status = source_metadata['status']
    except KeyError:
        return '"status" attribute missing'
    message = f"status: '{status}'. "
    if status == 'to-review':
        if 'preview' not in resource:
            return "{bucket}/{collection} should not have 'to-review' status".format(**resource['source'])
        source_records = await client.get_records(**source)
        preview_records = await client.get_records(**resource['preview'])
        diff = compare_collections(source_records, preview_records)
        if diff:
            return message + human_diff('source', 'preview', *diff)
    elif status == 'signed' or status is None:
        source_records = await client.get_records(**source)
        dest_records = await client.get_records(**resource['destination'])
        if 'preview' in resource:
            preview_records = await client.get_records(**resource['preview'])
            diff_preview = compare_collections(preview_records, dest_records)
            if diff_preview:
                return message + human_diff('preview', 'destination', *diff_preview)
            diff_source = compare_collections(source_records, preview_records)
            if diff_source:
                return message + human_diff('source', 'preview', *diff_source)
        else:
            diff_source = compare_collections(source_records, dest_records)
            if diff_source:
                return message + human_diff('source', 'destination', *diff_source)
    elif status == 'work-in-progress':
        pass
    else:
        return f"Unexpected status '{status}'"
    return None

async def func(root_url, secret_name=DEFAULT_NAME, expires_seconds=DEFAULT_EXPIRES_SECONDS, client_id='', access_token='', certificate=''):
    options = tc_utils.options_from_params(root_url, client_id, access_token, certificate)
    secrets = taskcluster.aio.Secrets(options)
    payload = {'expires': (utils.utcnow() + timedelta(seconds=expires_seconds)).isoformat(), 'secret': {'hello': 'beautiful world'}}
    await secrets.set(secret_name, payload)
    try:
        await secrets.get(secret_name)
    except taskcluster.exceptions.TaskclusterRestFailure:
        return (False, f'Secret {secret_name!r} could not be retrieved')
    await secrets.remove(secret_name)
    try:
        await secrets.get(secret_name)
        return (False, f'Secret {secret_name!r} was not removed')
    except taskcluster.exceptions.TaskclusterRestFailure as e:
        if getattr(e, 'status_code') != 404:
            raise
    return (True, {})

