def func(self, txn):
    vs = set(self.crdt_env.keys())
    vs_seen = set()
    for s in txn:
        if not self._var_free_join(s):
            return False
        s = cast(ast.SJoinAssign, s)
        vs_seen.add(s.x.x)
    for v in vs - vs_seen:
        crdt = self.crdt_env[v]
        if not self._has_bottom(crdt):
            return False
    return True

