def func(cls, certificate):
    text_output = [cls._format_field('SHA1 Fingerprint:', binascii.hexlify(certificate.fingerprint(hashes.SHA1())).decode('ascii')), cls._format_field('Common Name:', _get_subject_as_short_text(certificate)), cls._format_field('Issuer:', _get_issuer_as_short_text(certificate)), cls._format_field('Serial Number:', str(certificate.serial_number)), cls._format_field('Not Before:', certificate.not_valid_before.date().isoformat()), cls._format_field('Not After:', certificate.not_valid_after.date().isoformat()), cls._format_field('Public Key Algorithm:', certificate.public_key().__class__.__name__)]
    if certificate.signature_hash_algorithm:
        text_output.append(cls._format_field('Signature Algorithm:', certificate.signature_hash_algorithm.name))
    public_key = certificate.public_key()
    if isinstance(public_key, EllipticCurvePublicKey):
        text_output.append(cls._format_field('Key Size:', str(public_key.curve.key_size)))
        text_output.append(cls._format_field('Curve:', str(public_key.curve.name)))
    elif isinstance(public_key, RSAPublicKey):
        text_output.append(cls._format_field('Key Size:', str(public_key.key_size)))
        text_output.append(cls._format_field('Exponent:', str(public_key.public_numbers().e)))
    else:
        pass
    subj_alt_name_ext = parse_subject_alternative_name_extension(certificate)
    if subj_alt_name_ext.dns_names:
        text_output.append(cls._format_field('SubjAltName - DNS Names:', str(subj_alt_name_ext.dns_names)))
    if subj_alt_name_ext.ip_addresses:
        text_output.append(cls._format_field('SubjAltName - IP Addresses', str(subj_alt_name_ext.ip_addresses)))
    return text_output

def func(cls, verified_certificate_chain):
    has_whitelisted_cert = False
    has_blacklisted_cert = False
    for certificate in verified_certificate_chain:
        key_hash = binascii.hexlify(get_public_key_sha256(certificate)).decode('ascii')
        if key_hash in cls._CA_KEYS_BLACKLIST:
            has_blacklisted_cert = True
        if key_hash in cls._CA_KEYS_WHITELIST:
            has_whitelisted_cert = True
    distrust_enum = None
    if has_blacklisted_cert and (not has_whitelisted_cert):
        leaf_cert = verified_certificate_chain[0]
        if leaf_cert.not_valid_before < datetime(year=2016, month=6, day=1):
            distrust_enum = SymantecDistrustTimelineEnum.MARCH_2018
        else:
            distrust_enum = SymantecDistrustTimelineEnum.SEPTEMBER_2018
    return distrust_enum

