def func(self):
    max_y, max_x = self.get_maxyx()
    self.prev_buffer = self.buffer
    self.buffer = []
    tasks = self.schedule.tasks
    if not self.schedule.tasks:
        return
    self.run_hook()
    header_buffer = self.prerender_headers()
    for header in header_buffer:
        self.buffer.append(header)
    alternate = True
    current_line = 1
    time_slots = self.schedule.get_time_slots()
    for day in time_slots:
        day_has_tasks = False
        for hour in time_slots[day]:
            tasks = time_slots[day][hour]
            if tasks:
                day_has_tasks = True
        if day_has_tasks or not self.hide_empty:
            divider_buffer = self.prerender_divider(day, current_line)
            for divider_part in divider_buffer:
                self.buffer.append(divider_part)
            current_line += 1
            alternate = False
        for hour in time_slots[day]:
            tasks = time_slots[day][hour]
            if not tasks and (not self.hide_empty):
                empty_line_buffer = self.prerender_empty_line(alternate, current_line, hour, day)
                for part in empty_line_buffer:
                    self.buffer.append(part)
                current_line += 1
                alternate = not alternate
            for task_num, task in enumerate(tasks):
                task_buffer = self.prerender_task(task_num, task, alternate, hour, current_line, day)
                for part in task_buffer:
                    self.buffer.append(part)
                current_line += 1
                alternate = not alternate

def func(dst, data):
    len_data = len(data).to_bytes(4, byteorder='big')
    data_with_len = len_data + data
    sign = b'\x02'
    for i in range(2 ** 32):
        ibytes = i.to_bytes(4, byteorder='big')
        digest = Hash(dst)
        digest.update(data_with_len + ibytes)
        point_data = digest.finalize()[:CURVE.field_element_size]
        compressed_point = sign + point_data
        try:
            return CurvePoint.from_bytes(compressed_point)
        except ErrorInvalidCompressedPoint:
            pass
    raise ValueError('Could not hash input into the curve')

