def func(network, iterations=1000):
    A = network.adjacency_matrix(weighted=False)
    D = network.degrees()
    n = network.number_of_nodes()
    m = network.number_of_edges()
    C = {}
    num_communities = n
    community_to_nodes = {}
    c = 0
    for v in network.nodes.uids:
        C[v] = c
        community_to_nodes[c] = set([v])
        c += 1
    q = _Q_merge(network, A, D, n, m, C)
    for i in tqdm(range(iterations), desc='maximising modularity'):
        x, y = random.sample(sorted(community_to_nodes.keys()), 2)
        q_new = _Q_merge(network, A, D, n, m, C, merge=set([x, y]))
        if q_new > q:
            for v in community_to_nodes[x]:
                C[v] = y
            community_to_nodes[y] = community_to_nodes[y].union(community_to_nodes[x])
            q = q_new
            num_communities -= 1
            del community_to_nodes[x]
    return (C, q)

def func(self, *args, **kwargs):
    super().__init__()
    self.predicates = {}
    self.nonlookup_predicates = {}
    nonlookup_predicates = getattr(self, 'NONLOOKUP_PREDICATES', [])
    defined_predicate_keys = [predicate.key for predicate in self.OPTIONAL_PREDICATES + self.REQUIRED_PREDICATES + tuple(nonlookup_predicates)]
    for argument_name in kwargs.keys():
        if argument_name not in defined_predicate_keys:
            m = UnknownArgument.fmt.format(name=argument_name)
            raise UnknownArgument(m)
    for predicate_choice in self.REQUIRED_PREDICATES:
        key = predicate_choice.key
        if key not in kwargs:
            m = MissingArgument.fmt.format(name=key)
            raise MissingArgument(m)
        predicate = predicate_choice(value=kwargs[key])
        self.predicates[key] = predicate
    for predicate_choice in self.OPTIONAL_PREDICATES:
        key = predicate_choice.key
        if key in kwargs:
            predicate = predicate_choice(value=kwargs[key])
            self.predicates[key] = predicate
    if nonlookup_predicates:
        for predicate_choice in nonlookup_predicates:
            key = predicate_choice.key
            if key in kwargs:
                predicate = predicate_choice(value=kwargs[key])
                self.nonlookup_predicates[key] = predicate
    predicate_values = self.predicates.values()
    self.name = '--'.join([str(predicate) for predicate in predicate_values])
    self.sort_order = sum([predicate.rank for predicate in predicate_values])

def func(host, ports=PROBE_PORTS, probe_timeout=REQUESTS_TIMEOUT, match_udn=None):
    for port in ports:
        try:
            response = requests.get(f'http://{host}:{port}/setup.xml', timeout=probe_timeout)
            try:
                device = DeviceDescription.from_xml(response.content)
            except InvalidSchemaError:
                continue
            if match_udn and match_udn != device.udn:
                LOG.error('Reconnected to a different WeMo. Expected %s / Received %s', match_udn, device.udn)
                continue
            return port
        except requests.exceptions.ConnectTimeout:
            LOG.debug('Timed out connecting to %s on port %i, wemo is offline', host, port)
            break
        except requests.exceptions.Timeout:
            LOG.debug('No response from %s on port %i, continuing', host, port)
            continue
        except requests.exceptions.ConnectionError:
            pass
    return None

def func(self, resource_path, method, path_params=None, query_params=None, header_params=None, body=None, post_params=None, files=None, response_type=None, auth_settings=None, _return_http_data_only=None, collection_formats=None, _preload_content=True, _request_timeout=None):
    config = self.configuration
    header_params = header_params or {}
    header_params.update(self.default_headers)
    if self.cookie:
        header_params['Cookie'] = self.cookie
    if header_params:
        header_params = self.sanitize_for_serialization(header_params)
        header_params = dict(self.parameters_to_tuples(header_params, collection_formats))
    if path_params:
        path_params = self.sanitize_for_serialization(path_params)
        path_params = self.parameters_to_tuples(path_params, collection_formats)
        for k, v in path_params:
            resource_path = resource_path.replace('{%s}' % k, quote(str(v), safe=config.safe_chars_for_path_param))
    if query_params:
        query_params = self.sanitize_for_serialization(query_params)
        query_params = self.parameters_to_tuples(query_params, collection_formats)
    if post_params or files:
        post_params = self.prepare_post_parameters(post_params, files)
        post_params = self.sanitize_for_serialization(post_params)
        post_params = self.parameters_to_tuples(post_params, collection_formats)
    self.update_params_for_auth(header_params, query_params, auth_settings)
    if body:
        body = self.sanitize_for_serialization(body)
    url = self.configuration.host + resource_path
    response_data = self.request(method, url, query_params=query_params, headers=header_params, post_params=post_params, body=body, _preload_content=_preload_content, _request_timeout=_request_timeout)
    self.last_response = response_data
    return_data = response_data
    if _preload_content:
        if response_type:
            return_data = self.deserialize(response_data, response_type)
        else:
            return_data = None
    if _return_http_data_only:
        return return_data
    else:
        return (return_data, response_data.status, response_data.getheaders())

def func(org_wav_dir=ORG_WAV_DIR, tgt_wav_dir=TGT_WAV_DIR, org_xml_dir=ORG_XML_DIR):
    logging.info('Trimming wavs...')
    if not os.path.exists(os.path.join(tgt_wav_dir, 'TEXT')):
        os.makedirs(os.path.join(tgt_wav_dir, 'TEXT'))
    if not os.path.exists(os.path.join(tgt_wav_dir, 'WORDLIST')):
        os.makedirs(os.path.join(tgt_wav_dir, 'WORDLIST'))
    for fn in os.listdir(org_xml_dir):
        path = os.path.join(org_xml_dir, fn)
        prefix, _ = os.path.splitext(fn)
        if os.path.isdir(path):
            continue
        if not path.endswith('.xml'):
            continue
        logging.info('Trimming wavs from {}'.format(fn))
        rec_type, _, times, _ = pangloss.get_sents_times_and_translations(path)
        for i, (start_time, end_time) in enumerate(times):
            if prefix.endswith('PLUSEGG'):
                in_wav_path = os.path.join(org_wav_dir, prefix.upper()[:-len('PLUSEGG')]) + '.wav'
            else:
                in_wav_path = os.path.join(org_wav_dir, prefix.upper()) + '.wav'
            headmic_path = os.path.join(org_wav_dir, prefix.upper()) + '_HEADMIC.wav'
            if os.path.isfile(headmic_path):
                in_wav_path = headmic_path
            out_wav_path = os.path.join(tgt_wav_dir, rec_type, '%s.%d.wav' % (prefix, i))
            if not os.path.isfile(in_wav_path):
                raise PersephoneException('{} not a file.'.format(in_wav_path))
            start_time = start_time * ureg.seconds
            end_time = end_time * ureg.seconds
            wav.trim_wav_ms(Path(in_wav_path), Path(out_wav_path), start_time.to(ureg.milliseconds).magnitude, end_time.to(ureg.milliseconds).magnitude)

