def func(self, data):
    self._buffer += data
    log_binary(_LOGGER, 'Received data', Data=data)
    while len(self._buffer) >= HEADER_LENGTH:
        payload_length = HEADER_LENGTH + int.from_bytes(self._buffer[1:HEADER_LENGTH], byteorder='big')
        if len(self._buffer) < payload_length:
            _LOGGER.debug('Require %d bytes but only %d in buffer', payload_length, len(self._buffer))
            break
        header = self._buffer[0:HEADER_LENGTH]
        payload = self._buffer[HEADER_LENGTH:payload_length]
        self._buffer = self._buffer[payload_length:]
        try:
            if self._chacha and len(payload) > 0:
                payload = self._chacha.decrypt(payload, aad=header)
            self._listener.frame_received(FrameType(header[0]), payload)
        except Exception:
            _LOGGER.exception('failed to handle frame')

def func(self):
    self.server_name, self.server_port = self.server_address
    self._sockets = []
    if not self.server_name:
        addrinfo_array = [(socket.AF_INET6, socket.SOCK_STREAM, '', '', ''), (socket.AF_INET, socket.SOCK_STREAM, '', '', '')]
    else:
        addrinfo_array = socket.getaddrinfo(self.server_name, self.server_port, socket.AF_UNSPEC, socket.SOCK_STREAM, socket.IPPROTO_TCP)
    for addrinfo in addrinfo_array:
        self._logger.info('Create socket on: %r', addrinfo)
        family, socktype, proto, canonname, sockaddr = addrinfo
        try:
            socket_ = socket.socket(family, socktype)
        except Exception as e:
            self._logger.info('Skip by failure: %r', e)
            continue
        server_options = self.websocket_server_options
        if server_options.use_tls:
            if server_options.tls_module == _TLS_BY_STANDARD_MODULE:
                if server_options.tls_client_auth:
                    if server_options.tls_client_cert_optional:
                        client_cert_ = ssl.CERT_OPTIONAL
                    else:
                        client_cert_ = ssl.CERT_REQUIRED
                else:
                    client_cert_ = ssl.CERT_NONE
                socket_ = ssl.wrap_socket(socket_, keyfile=server_options.private_key, certfile=server_options.certificate, ssl_version=ssl.PROTOCOL_SSLv23, ca_certs=server_options.tls_client_ca, cert_reqs=client_cert_, do_handshake_on_connect=False)
        self._sockets.append((socket_, addrinfo))

