async def func(self, data, clear=True):
    if not isinstance(data, list):
        data = [data]
    result = []
    for entry in data:
        if not isinstance(entry, dict):
            raise KongError('dictionary required')
        entry = entry.copy()
        groups = entry.pop('groups', [])
        auths = entry.pop('auths', [])
        udata = entry.copy()
        id_ = udata.pop('id', None)
        username = None
        if not id_:
            username = udata.pop('username', None)
            if not username:
                raise KongError('Consumer username or id is required')
        uid = cast(str, id_ or username)
        try:
            entity = await self.get(uid)
        except KongResponseError as exc:
            if exc.status == 404:
                entity = await self.create(**entry)
            else:
                raise
        else:
            if entry:
                entity = await self.update(uid, **udata)
        consumer = cast(Consumer, entity)
        acls = await consumer.acls.get_list()
        current_groups = dict(((a['group'], a) for a in acls))
        for group in groups:
            if group not in current_groups:
                await consumer.acls.create(group=group)
            else:
                current_groups.pop(group)
        for acl in current_groups.values():
            await consumer.acls.delete(acl['id'])
        await self.apply_credentials(auths, consumer)
        result.append(consumer.data)
    return result

def func(self, operation, system_qubits):
    cast(Tuple[cirq.LineQubit], system_qubits)
    num_qubits = len(system_qubits)
    xtlk_arr = np.zeros(num_qubits)
    idx_list = []
    for qubit in operation.qubits:
        idx = system_qubits.index(qubit)
        idx_list.append(idx)
        neighbors = [idx - 1, idx + 1]
        for neigh_idx in neighbors:
            if neigh_idx >= 0 and neigh_idx < num_qubits:
                xtlk_arr[neigh_idx] = self.noise_op_dict['crosstalk']
    for idx in idx_list:
        xtlk_arr[idx] = 0
    xtlk_op_list = []
    op_str = get_op_string(operation)
    gate = cast(cirq.EigenGate, gate_dict[op_str])
    if len(operation.qubits) == 1:
        for idx in xtlk_arr.nonzero()[0]:
            exponent = operation.gate.exponent
            exponent = exponent * xtlk_arr[idx]
            xtlk_op = gate.on(system_qubits[idx]) ** exponent
            xtlk_op_list.append(xtlk_op)
    elif len(operation.qubits) == 2:
        for op_qubit in operation.qubits:
            for idx in xtlk_arr.nonzero()[0]:
                exponent = operation.gate.exponent
                exponent = exponent * xtlk_arr[idx]
                xtlk_op = gate.on(op_qubit, system_qubits[idx]) ** exponent
                xtlk_op_list.append(xtlk_op)
    return xtlk_op_list

def func(self, tok):
    absolute_start_line, start_col = tok.start
    absolute_end_line, end_col = tok.end
    lines = tok.line.splitlines(keepends=True)
    end_line = absolute_end_line - absolute_start_line
    start_line = 0
    if not lines or (start_line == end_line and start_col == end_col):
        return ''
    buffer = []
    if self.last_line != absolute_start_line:
        self.last_col = 0
    if self.last_col < start_col:
        buffer.append(lines[0][self.last_col:start_col])
    self.last_line = absolute_end_line
    self.last_col = end_col
    if start_line == end_line:
        buffer.append(lines[start_line][start_col:end_col])
    else:
        buffer.append(lines[start_line][start_col:])
        for line_num in range(start_line + 1, end_line):
            buffer.append(lines[line_num])
        buffer.append(lines[end_line][:end_col])
    return ''.join(buffer)

def func(iou, pathfinding_service, service_fee, one_to_n_address):
    if service_fee == 0:
        if iou is not None:
            log.debug('Discarding IOU, service fee is 0', sender=to_checksum_address(iou.sender), total_amount=iou.amount, claimable_until=iou.claimable_until)
        else:
            log.debug('No IOU and service fee is 0')
        return
    if iou is None:
        raise exceptions.MissingIOU
    log.debug('Checking IOU', sender=to_checksum_address(iou.sender), total_amount=iou.amount, claimable_until=iou.claimable_until)
    if not is_same_address(iou.receiver, pathfinding_service.address):
        raise exceptions.WrongIOURecipient(expected=pathfinding_service.address)
    if iou.chain_id != pathfinding_service.chain_id:
        raise exceptions.UnsupportedChainID(expected=pathfinding_service.chain_id)
    if iou.one_to_n_address != one_to_n_address:
        raise exceptions.WrongOneToNAddress(expected=one_to_n_address, got=iou.one_to_n_address)
    if not iou.is_signature_valid():
        raise exceptions.InvalidSignature
    latest_block = pathfinding_service.blockchain_state.latest_committed_block
    active_iou = pathfinding_service.database.get_iou(sender=iou.sender, claimed=False)
    if active_iou:
        if active_iou.claimable_until != iou.claimable_until:
            raise exceptions.UseThisIOU(iou=active_iou.Schema().dump(active_iou))
        expected_amount = active_iou.amount + service_fee
    else:
        claimed_iou = pathfinding_service.database.get_iou(sender=iou.sender, claimable_until=iou.claimable_until, claimed=True)
        if claimed_iou:
            raise exceptions.IOUAlreadyClaimed
        min_expiry = get_posix_utc_time_now() + MIN_IOU_EXPIRY
        if iou.claimable_until < min_expiry:
            raise exceptions.IOUExpiredTooEarly(min_expiry=min_expiry, claimable_until_received=iou.claimable_until)
        expected_amount = service_fee
    if iou.amount < expected_amount:
        raise exceptions.InsufficientServicePayment(expected_amount=expected_amount, actual_amount=iou.amount)
    udc = pathfinding_service.user_deposit_contract
    udc_balance = get_pessimistic_udc_balance(udc=udc, address=iou.sender, from_block=BlockNumber(latest_block - pathfinding_service.required_confirmations), to_block=latest_block)
    required_deposit = round(expected_amount * UDC_SECURITY_MARGIN_FACTOR_PFS)
    if udc_balance < required_deposit:
        raise exceptions.DepositTooLow(required_deposit=required_deposit, seen_deposit=udc_balance, block_number=latest_block)
    log.info('Received service fee', sender=iou.sender, expected_amount=expected_amount, total_amount=iou.amount, added_amount=expected_amount - service_fee)
    iou.claimed = False
    pathfinding_service.database.upsert_iou(iou)

