    logger.debug('pulses per quarter note: %i', ppqn)
    tempo = midi.tracks[0].events[0][1].metadata['tempo']
    logger.debug('tempo: %i', tempo)
    ticklen = tempo / ppqn
    logger.debug('ticklen: %f', ticklen)
    ticklen_mult = DEFAULT_TICKLEN / ticklen
    tokens.append('start')
    cumulative_delta_time = 0
    for i, (delta_time, event) in enumerate(midi.tracks[1].events):
        if self._max_tokens is not None:
            if len(tokens) >= self._max_tokens:
                yield ' '.join(tokens[:self._max_tokens])
                tokens = ['continue', *tokens[self._max_tokens:]]
        cumulative_delta_time += round(delta_time / ticklen_mult)
        if event.event_type == 'NoteOn':
            metadata = event.metadata
            if cumulative_delta_time > 0:
                if tokens[-1] != 'start':
                    tokens.extend(split_waits(cumulative_delta_time))
                cumulative_delta_time = 0
            if metadata['velocity'] > 0:
                velocity = 60
            else:
                velocity = 0
            tokens.append(f"note:{metadata['key']}:{velocity}")
    tokens.append('end')
    if self._max_tokens is not None:
        if len(tokens) >= self._max_tokens:
            yield ' '.join(tokens[:self._max_tokens])
            tokens = tokens[self._max_tokens:]
    yield ' '.join(tokens)

def func(converter, filepath, overwrite, name=None):
    if not filepath.name.endswith('.safe'):
        return exit_codes.FILE_IS_NOT_SAFE_FILE
    with filepath.open('rb') as f:
        lines = f.read().splitlines()
        decrypted_lines = converter.decrypt_lines(lines)
        if name is not None:
            if name.endswith('.safe'):
                print(f'The name given ({name}) cannot have the `.safe` extension.')
                return exit_codes.CONVERSION_FAILED
        decrypted_fpath = filepath.with_name(filepath.stem) if name is None else filepath.with_name(name)
        try:
            _store_content_into_path(decrypted_fpath, decrypted_lines, overwrite)
        except ValueError as ve:
            print(f'An error occurred:\n{ve}')
            return exit_codes.CONVERSION_FAILED
        return exit_codes.SUCCESS

