def func(arr, element):
    start = 0
    end = len(arr) - 1
    while start <= end and arr[start] <= element <= arr[end]:
        position = math.floor(start + (end - start) * (element - arr[start]) / (arr[end] - arr[start]))
        if arr[position] == element:
            return position
        if arr[position] > element:
            end = position - 1
        else:
            start = position + 1
    return -1

