def func(addr, privkey):
    if addr.amount:
        amount = Decimal(str(addr.amount))
        if amount * 10 ** 12 % 10:
            raise ValueError('Cannot encode {}: too many decimal places'.format(addr.amount))
        amount = addr.currency + shorten_amount(amount)
    else:
        amount = addr.currency if addr.currency else ''
    hrp = 'lm' + amount
    data = bitstring.pack('uint:35', addr.date)
    data += tagged_bytes('p', addr.paymenthash)
    tags_set = set()
    for k, v in addr.tags:
        if k in ('d', 'h', 'n', 'x'):
            if k in tags_set:
                raise ValueError("Duplicate '{}' tag".format(k))
        if k == 'r':
            route = bitstring.BitArray()
            for step in v:
                pubkey, channel, feebase, feerate, cltv = step
                route.append(bitstring.BitArray(pubkey) + bitstring.BitArray(channel) + bitstring.pack('intbe:32', feebase) + bitstring.pack('intbe:32', feerate) + bitstring.pack('intbe:16', cltv))
            data += tagged('r', route)
        elif k == 'f':
            data += encode_fallback(v, addr.currency)
        elif k == 'd':
            data += tagged_bytes('d', v.encode())
        elif k == 'x':
            expirybits = bitstring.pack('intbe:64', v)[4:64]
            while expirybits.startswith('0b00000'):
                expirybits = expirybits[5:]
            data += tagged('x', expirybits)
        elif k == 'h':
            data += tagged_bytes('h', hashlib.sha256(v.encode('utf-8')).digest())
        elif k == 'n':
            data += tagged_bytes('n', v)
        elif k == 't':
            data += tagged_bytes('t', v)
        else:
            raise ValueError('Unknown tag {}'.format(k))
        tags_set.add(k)
    if 'd' in tags_set and 'h' in tags_set:
        raise ValueError("Cannot include both 'd' and 'h'")
    if not 'd' in tags_set and (not 'h' in tags_set):
        raise ValueError("Must include either 'd' or 'h'")
    privkey = secp256k1.PrivateKey(bytes(unhexlify(privkey)))
    sig = privkey.ecdsa_sign_recoverable(bytearray([ord(c) for c in hrp]) + data.tobytes())
    sig, recid = privkey.ecdsa_recoverable_serialize(sig)
    data += bytes(sig) + bytes([recid])
    return bech32_encode(hrp, bitarray_to_u5(data))

def func(self):
    try:
        if self.url.scheme == 'http':
            conn = HTTPConnection(self.host, self.port)
        elif self.url.scheme == 'https':
            ssl_context = None
            if not self.verify_tls:
                ssl_context = ssl._create_unverified_context()
            conn = HTTPSConnection(self.host, self.port, context=ssl_context)
        else:
            raise ValueError(f'Unsupported URL scheme: "{self.url.scheme}"')
        self._send_request(conn)
        response = conn.getresponse()
        status = str(response.status)
        if not self._validate_response(response):
            return False
        if status == self.status or self.status_re.match(status):
            conn.close()
            return True
    except (HTTPException, socket.timeout, socket.error) as ex:
        log.debug('Executor process not healthy yet', command=self.command, error=ex)
        time.sleep(0.1)
        return False
    return False

