def func(self, token):
    from jose import jwt, exceptions as jose_exceptions
    try:
        header = jwt.get_unverified_header(token)
    except jose_exceptions.JWTError as err:
        raise ValueError(str(err)) from None
    kid = header.get('kid')
    if kid is None:
        raise ValueError('No kid in header')
    key = None
    for key_dict in self.jwt_keyset['keys']:
        if key_dict['kid'] == kid:
            key = key_dict
            break
    if not key:
        raise ValueError('Unable to locate kid ({}) in keyset'.format(kid))
    try:
        return jwt.decode(token, key, audience=self.cognito_client_id, options={'verify_exp': False})
    except jose_exceptions.JWTError as err:
        raise ValueError(str(err)) from None

