def func(app, trusted_networks, use_auth, support_legacy=False, api_password=None):
    @middleware
    async def auth_middleware(request, handler):
        authenticated = False
        if use_auth and (HTTP_HEADER_HA_AUTH in request.headers or DATA_API_PASSWORD in request.query):
            _LOGGER.warning('Please change to use bearer token access %s', request.path)
        legacy_auth = (not use_auth or support_legacy) and api_password
        if hdrs.AUTHORIZATION in request.headers and await async_validate_auth_header(request, api_password if legacy_auth else None):
            authenticated = True
        elif legacy_auth and HTTP_HEADER_HA_AUTH in request.headers and hmac.compare_digest(api_password.encode('utf-8'), request.headers[HTTP_HEADER_HA_AUTH].encode('utf-8')):
            authenticated = True
        elif legacy_auth and DATA_API_PASSWORD in request.query and hmac.compare_digest(api_password.encode('utf-8'), request.query[DATA_API_PASSWORD].encode('utf-8')):
            authenticated = True
        elif _is_trusted_ip(request, trusted_networks):
            authenticated = True
        elif not use_auth and api_password is None:
            authenticated = True
        request[KEY_AUTHENTICATED] = authenticated
        return await handler(request)
    async def auth_startup(app):
        app.middlewares.append(auth_middleware)
    app.on_startup.append(auth_startup)

async def func(request, api_password=None):
    if hdrs.AUTHORIZATION not in request.headers:
        return False
    try:
        auth_type, auth_val = request.headers.get(hdrs.AUTHORIZATION).split(' ', 1)
    except ValueError:
        return False
    if auth_type == 'Bearer':
        hass = request.app['hass']
        access_token = hass.auth.async_get_access_token(auth_val)
        if access_token is None:
            return False
        request['hass_user'] = access_token.refresh_token.user
        return True
    elif auth_type == 'Basic' and api_password is not None:
        decoded = base64.b64decode(auth_val).decode('utf-8')
        try:
            username, password = decoded.split(':', 1)
        except ValueError:
            return False
        if username != 'homeassistant':
            return False
        return hmac.compare_digest(api_password.encode('utf-8'), password.encode('utf-8'))
    else:
        return False

def func(glob, word_boundary=False):
    chunks = []
    for chunk in _WILDCARD_RUN.split(glob):
        if not _WILDCARD_RUN.match(chunk):
            chunks.append(re.escape(chunk))
            continue
        qmarks = chunk.count('?')
        if '*' in chunk:
            chunks.append('.{%d,}' % qmarks)
        else:
            chunks.append('.{%d}' % qmarks)
    res = ''.join(chunks)
    if word_boundary:
        res = re_word_boundary(res)
    else:
        res = '\\A' + res + '\\Z'
    return re.compile(res, re.IGNORECASE)

def func(self, content):
    raw = {}
    root = etree.fromstring(content, parser=etree.XMLParser(resolve_entities=False))
    for child in root:
        raw[child.tag] = child.text
    formatted = self.format(raw)
    msg_type = formatted['type']
    msg_parser = getattr(self, 'parse_{0}'.format(msg_type), None)
    if callable(msg_parser):
        parsed = msg_parser(raw)
    else:
        parsed = self.parse_invalid_type(raw)
    formatted.update(parsed)
    return formatted

def func(exts_opts):
    result = {}
    last_name = None
    while exts_opts:
        name, exts_opts = _get_sshstr(exts_opts)
        bname = bytes(name)
        if bname in result:
            raise ValueError('Duplicate name')
        if last_name is not None and bname < last_name:
            raise ValueError('Fields not lexically sorted')
        value, exts_opts = _get_sshstr(exts_opts)
        if len(value) > 0:
            value, extra = _get_sshstr(value)
            if len(extra) > 0:
                raise ValueError('Unexpected extra data after value')
        result[bname] = bytes(value)
        last_name = bname
    return result

